void reverseString(std::string& str) {
    // Remove whitespace characters, punctuation marks, and special characters
    str.erase(std::remove_if(str.begin(), str.end(), [](char c) {
        return !std::isalnum(c);
    }), str.end());

    // Reverse the alphanumeric characters
    std::reverse(str.begin(), str.end());

    // Reverse the case of each alphabetic character
    for (char& c : str) {
        if (std::isalpha(c)) {
            if (std::islower(c)) {
                c = std::toupper(c);
            } else {
                c = std::tolower(c);
            }
        }
    }
}

int main() {
    std::string str = "Hello World! 123";

    reverseString(str);

    std::cout << str << std::endl;

    return 0;
}

