function generateCombinations(arr, subset, index, k, combinations, primes) {
  if (subset.length === k) {
    combinations.push(subset.slice());
    return;
  }

  for (let i = index; i < arr.length; i++) {
    subset.push(arr[i]);
    generateCombinations(arr, subset, i + 1, k, combinations, primes);
    subset.pop();
  }
}

function getPrimes(arr) {
  const primes = [];
  for (let i = 0; i < arr.length; i++) {
    if (isPrime(arr[i])) {
      primes.push(arr[i]);
    }
  }
  return primes;
}

function isPrime(num) {
  if (num < 2) return false;
  for (let i = 2; i <= Math.sqrt(num); i++) {
    if (num % i === 0) return false;
  }
  return true;
}
