function validateUsername(username) {
  // Check if the username is between 6 and 20 characters
  if (username.length < 6 || username.length > 20) {
    return false;
  }

  // Check if the username starts with an alphabet
  if (!username[0].match(/[a-zA-Z]/)) {
    return false;
  }

  // Check if the username ends with a digit
  if (!username[username.length - 1].match(/[0-9]/)) {
    return false;
  }

  // Check if the username contains only alphabets and digits
  if (!username.match(/^[a-zA-Z0-9]+$/)) {
    return false;
  }

  return true;
}

