def longest_common_subsequence(s1, s2):
    m = len(s1)
    n = len(s2)

    # Create a matrix to store the lengths of common subsequences
    dp = [[0] * (n+1) for _ in range(m+1)]

    # Fill in the matrix using dynamic programming
    for i in range(m+1):
        for j in range(n+1):
            if i == 0 or j == 0:
