public class BubbleSortDescending {
    public static void main(String[] args) {
        int[] array = {5, 2, 8, 1, 3};

        // Modified Bubble sort algorithm for descending order
        int n = array.length;
        for (int i = 0; i < n - 1; i++) {
            for (int j = 0; j < n - i - 1; j++) {
                if (array[j] < array[j + 1]) { // Modification: change the comparison operator to <
                    // Swap array[j] and array[j+1]
