function copyAndSort(arr) {
  let oddArr = [];

  // Helper function to check if a number is odd
  function isOdd(num) {
    return num % 2 !== 0;
  }

  // Helper function to sort array using merge sort algorithm
  function mergeSort(arr) {
    if (arr.length <= 1) {
      return arr;
    }

    const mid = Math.floor(arr.length / 2);
    const left = arr.slice(0, mid);
    const right = arr.slice(mid);

    return merge(mergeSort(left), mergeSort(right));
  }

  // Helper function to merge two sorted arrays
  function merge(left, right) {
    let result = [];
    let leftIndex = 0;
    let rightIndex = 0;

    while (leftIndex < left.length && rightIndex < right.length) {
      if (left[leftIndex] < right[rightIndex]) {
        result.push(left[leftIndex]);
        leftIndex++;
      } else {
        result.push(right[rightIndex]);
        rightIndex++;
      }
    }

    return result.concat(left.slice(leftIndex)).concat(right.slice(rightIndex));
  }

  // Main function to copy and sort array
  function copyAndSortRecursive(arr) {
    if (arr.length === 0) {
      return oddArr;
    }

    const first = arr[0];
    const rest = arr.slice(1);

    if (isOdd(first)) {
      oddArr.push(first);
    }

    return copyAndSortRecursive(rest);
  }

  copyAndSortRecursive(arr);

  // Sort the odd array using merge sort
  const sortedArr = mergeSort(oddArr);

  return sortedArr;
}

