```python
def celsius_to_fahrenheit(celsius):
    try:
        if -273.15 <= celsius <= 1000:
            fahrenheit = (celsius * 9/5) + 32
            return fahrenheit
        else:
            raise ValueError("Temperature value should be between -273.15°C and 1000°C.")
    except ValueError as err:
        print(f"Error: {err}")
        return None

def fahrenheit_to_celsius(fahrenheit):
    try:
        celsius = (fahrenheit - 32) * 5/9
        if -459.67 <= fahrenheit <= 1832:
            return celsius
        else:
            raise ValueError("Temperature value should be between -459.67°F and 1832°F.")
    except ValueError as err:
        print(f"Error: {err}")
        return None

def main():
    while True:
        conversion_type = input("Choose conversion type (1 for Celsius to Fahrenheit, 2 for Fahrenheit to Celsius): ")
        if conversion_type not in ['1', '2']:
            print("Invalid input. Please choose 1 or 2.")
            continue

        try:
            temperature = float(input("Enter the temperature value: "))
        except ValueError:
            print("Invalid temperature value. Please enter a number.")
            continue

        if conversion_type == '1':
            converted_temp = celsius_to_fahrenheit(temperature)
            if converted_temp is not None:
                print(f"{temperature}°C is equal to {converted_temp}°F.")
        else:
            converted_temp = fahrenheit_to_celsius(temperature)
            if converted_temp is not None:
                print(f"{temperature}°F is equal to {converted_temp}°C.")

        break

if __name__ == '__main__':
