import java.util.Scanner;

public class CircleCalculator {
    private static final double PI = 3.14159;
    private static final Map<Double, Double> cache = new HashMap<>();

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        boolean exitProgram = false;

        while (!exitProgram) {
            System.out.println("Choose an option:");
            System.out.println("1. Calculate area");
            System.out.println("2. Calculate circumference");
            System.out.println("3. Exit");

            int option = scanner.nextInt();
            scanner.nextLine(); // Consume the newline character

            if (option == 3) {
                exitProgram = true;
                continue;
            }

            System.out.println("Enter the radius:");
            double radius = getValidRadius(scanner);

            if (!cache.containsKey(radius)) {
                double convertedRadius = convertRadius(radius);
                double result = calculate(option, convertedRadius);
                cache.put(radius, result);
            }

            double result = cache.get(radius);
            displayResult(option, radius, result);
        }
    }

    private static double getValidRadius(Scanner scanner) {
        double radius;

        while (true) {
            if (scanner.hasNextDouble()) {
                radius = scanner.nextDouble();
                if (radius > 0) {
                    break;
                }
            }

            System.out.println("Invalid radius. Please enter a positive numeric value:");
            scanner.nextLine(); // Consume the invalid input
        }

        return radius;
    }

    private static double convertRadius(double radius) {
        Scanner scanner = new Scanner(System.in);

        System.out.println("Choose a unit for the radius:");
        System.out.println("1. Inches");
        System.out.println("2. Centimeters");
        System.out.println("3. Meters");

        int option = scanner.nextInt();
        scanner.nextLine(); // Consume the newline character

        switch (option) {
            case 1:
                return radius * 0.0254; // Convert inches to meters
            case 2:
                return radius * 0.01; // Convert centimeters to meters
            default:
                return radius;
        }
    }

    private static double calculate(int option, double radius) {
        switch (option) {
            case 1:
                return 4 * PI * Math.pow(radius, 2); // Calculate surface area of a sphere
            case 2:
                return (4 * PI * Math.pow(radius, 3)) / 3; // Calculate volume of a sphere
            default:
                return 0;
        }
    }

    private static void displayResult(int option, double radius, double result) {
        switch (option) {
            case 1:
                System.out.printf("The surface area of a sphere with radius %.2f meters is %.2f square meters.%n",
                        radius, result);
                break;
            case 2:
                System.out.printf("The volume of a sphere with radius %.2f meters is %.2f cubic meters.%n",
                        radius, result);
                break;
        }
    }
}

