function selectAndHighlightContainers() {
  const mainDiv = document.getElementById("main");
  const containerDivs = mainDiv.getElementsByTagName("div");

  const stack = [...containerDivs]; // Use a stack to keep track of div elements to visit
  while (stack.length > 0) {
    const currentDiv = stack.pop(); // Pop the last element from the stack

    if (currentDiv.classList.contains("container")) {
      const highlightDiv = document.createElement("div");
      highlightDiv.classList.add("highlight");
      currentDiv.appendChild(highlightDiv);
    }

    // Add the child div elements to the stack
    const childrenDivs = currentDiv.getElementsByTagName("div");
    for (let i = childrenDivs.length - 1; i >= 0; i--) {
      stack.push(childrenDivs[i]);
    }
  }
}

