To find the kth largest number in an array, we can use the QuickSelect algorithm. QuickSelect is an efficient algorithm for finding the kth smallest element in an unsorted array.

The main idea behind QuickSelect is to select a pivot element and partition the array such that all elements less than the pivot are on the left, and all elements greater than the pivot are on the right. If the pivot is at index k, then we have found the kth smallest element. If the pivot is at a higher index, we recursively search in the left subarray. If the pivot is at a lower index, we recursively search in the right subarray.

Here is the Python implementation of the algorithm:

def quick_select(arr, left, right, k):
    if left == right:
        return arr[left]

    pivot_index = partition(arr, left, right)

    if pivot_index == k:
        return arr[pivot_index]
    elif pivot_index < k:
        return quick_select(arr, pivot_index + 1, right, k)
    else:
        return quick_select(arr, left, pivot_index - 1, k)

def partition(arr, left, right):
    pivot = arr[right]
    i = left - 1

    for j in range(left, right):
        if arr[j] <= pivot:
            i += 1
            arr[i], arr[j] = arr[j], arr[i]

    arr[i + 1], arr[right] = arr[right], arr[i + 1]

    return i + 1

def find_kth_largest(arr, k):
    if k < 1 or k > len(arr):
        return None

    return quick_select(arr, 0, len(arr) - 1, len(arr) - k)

# Test the implementation
