def measure_access_time(data_structure, size, index, iterations):
    total_time = 0
    for _ in range(iterations):
        start_time = time.time()
        data_structure(size).access_element(index)
        end_time = time.time()
        total_time += end_time - start_time
    average_time = total_time / iterations
    return average_time

