```java
import java.util.ArrayList;
import java.util.List;

public class SegmentedSieve {
    public static List<Integer> segmentedSieve(int n) {
        int limit = (int) Math.sqrt(n) + 1;
        List<Integer> primes = new ArrayList<>();

        // Sieve of Eratosthenes for small primes
        boolean[] isPrime = new boolean[limit + 1];
        for (int i = 2; i <= limit; i++) {
            isPrime[i] = true;
        }
        for (int i = 2; i <= limit; i++) {
            if (isPrime[i]) {
                primes.add(i);
                for (int j = i * i; j <= limit; j += i) {
                    isPrime[j] = false;
                }
            }
        }

        // Segmented sieve for larger primes
        int low = limit + 1;
        int high = Math.min(limit * 2, n);
        while (low <= n) {
            boolean[] segment = new boolean[high - low + 1];
            for (int prime : primes) {
                int start = (low / prime) * prime;
                if (start < low) {
                    start += prime;
                }
                for (int j = start; j <= high; j += prime) {
                    segment[j - low] = true;
                }
            }
            for (int i = low; i <= high; i++) {
                if (!segment[i - low]) {
                    primes.add(i);
                }
            }
            low += limit;
            high = Math.min(high + limit, n);
        }

        return primes;
    }

    public static void main(String[] args) {
        int n = 100;
        List<Integer> primes = segmentedSieve(n);
        System.out.println("Prime numbers up to " + n + ":");
        for (int prime : primes) {
            System.out.print(prime + " ");
        }
    }
}
```

This implementation first uses the Sieve of Eratosthenes to find all the small primes up to the square root of the given number. Then, it performs a segmented sieve algorithm to find the larger primes. The algorithm divides the range from the square root of the number to the given number into segments and marks the multiples of the primes found in the small prime sieve within each segment. Finally, it returns a list of all the prime numbers found.

The time complexity of this algorithm is O(n log log n), as required.

