        if grade is not None and grade not in ['A', 'B', 'C', 'D', 'F']:
            raise ValueError("Invalid grade")
        if gpa is not None and (gpa < 0.0 or gpa > 4.0):
            raise ValueError("Invalid GPA")

        if age is not None:
            student['age'] = age
        if course is not None:
            student['course'] = course
        if grade is not None:
            student['grade'] = grade
        if gpa is not None:
            student['gpa'] = gpa

    def get_student(self, name):
        if name not in self.students:
            raise ValueError("Student not found")
        return self.students[name]

    def delete_student(self, name):
        if name not in self.students:
            raise ValueError("Student not found")
        del self.students[name]

    def get_students_by_age_range(self, min_age, max_age):
        students = []
        for name, details in self.students.items():
            age = details['age']
            if age >= min_age and age <= max_age:
                students.append((name, details))
        return students

    def get_students_by_grade_range(self, min_grade, max_grade):
        students = []
        for name, details in self.students.items():
            grade = details['grade']
            if grade >= min_grade and grade <= max_grade:
                students.append((name, details))
        return students

    def get_students_by_gpa_range(self, min_gpa, max_gpa):
        students = []
        for name, details in self.students.items():
            gpa = details['gpa']
            if gpa >= min_gpa and gpa <= max_gpa:
                students.append((name, details))
        return students

    def get_top_performing_student(self):
        top_student = None
        top_gpa = -1

        for name, details in self.students.items():
            gpa = details['gpa']
            if gpa > top_gpa:
                top_gpa = gpa
                top_student = (name, details)

        return top_student

    def get_average_gpa(self):
        total_gpa = 0.0
        count = 0

        for details in self.students.values():
            total_gpa += details['gpa']
            count += 1

        if count > 0:
            return total_gpa / count
        else:
            return 0.0

    def get_num_students_in_course(self, course):
        count = 0

        for details in self.students.values():
            if details['course'] == course:
                count += 1

        return count
