        {
            var query = new QueryDefinition("SELECT * FROM c WHERE c.postId = @postId")
                .WithParameter("@postId", postId);

            var iterator = container.GetItemQueryIterator<UserPost>(query);
            var result = await iterator.ReadNextAsync();

            return result.FirstOrDefault();
        }
        catch (Exception)
        {
            return null;
        }
    }

    public async Task<List<UserPost>> GetUserPostsByUserId(string userId)
    {
        var query = new QueryDefinition("SELECT * FROM c WHERE c.userId = @userId")
            .WithParameter("@userId", userId);

        var iterator = container.GetItemQueryIterator<UserPost>(query);
        var results = new List<UserPost>();

        while (iterator.HasMoreResults)
        {
            var response = await iterator.ReadNextAsync();
            results.AddRange(response);
        }

        return results;
    }

