    {
        var userPost = await GetUserPost(postId);

        if (userPost == null)
            return null;

        userPost.ContentText = newContentText;

        await container.ReplaceItemAsync(userPost, userPost.PostId, new PartitionKey(userPost.UserId));

        return userPost;
    }

    public async Task<UserPost> IncrementUserPostLikes(string postId)
    {
        var userPost = await GetUserPost(postId);

        if (userPost == null)
            return null;

        userPost.NumberOfLikes++;

        await container.ReplaceItemAsync(userPost, userPost.PostId, new PartitionKey(userPost.UserId));

        return userPost;
    }

    public async Task<bool> DeleteUserPost(string postId)
    {
        var userPost = await GetUserPost(postId);

        if (userPost == null)
            return false;

        await container.DeleteItemAsync<UserPost>(userPost.PostId, new PartitionKey(userPost.UserId));

