Here is the implementation of the recursive binary search algorithm that handles duplicates and arrays sorted in ascending or descending order:

```python
def recursive_binary_search(arr, target, low, high, is_ascending):
    if low > high:
        return -1

    mid = (low + high) // 2

    if arr[mid] == target:
        if is_ascending:
            if mid > 0 and arr[mid - 1] == target:
                return recursive_binary_search(arr, target, low, mid - 1, is_ascending)
            else:
                return mid
        else:
            if mid < len(arr) - 1 and arr[mid + 1] == target:
                return recursive_binary_search(arr, target, mid + 1, high, is_ascending)
            else:
                return mid
    elif (is_ascending and arr[mid] > target) or (not is_ascending and arr[mid] < target):
        return recursive_binary_search(arr, target, low, mid - 1, is_ascending)
    else:
        return recursive_binary_search(arr, target, mid + 1, high, is_ascending)


def binary_search(arr, target, is_ascending=True):
    if is_ascending:
        return recursive_binary_search(arr, target, 0, len(arr) - 1, is_ascending)
    else:
        return recursive_binary_search(arr, target, len(arr) - 1, 0, is_ascending)
```

To use the `binary_search` function, you can pass in the sorted array, the target value, and an optional argument `is_ascending` to indicate whether the array is sorted in ascending or descending order. By default, the function assumes the array is sorted in ascending order.

Here's an example of how to use the `binary_search` function:

```python
arr = [1, 2, 3, 4, 4, 5, 5, 6, 7, 8]
