void findMaxAndMin(int arr[], int size, int& max, int& min) {
    max = arr[0]; // Assume the first element as maximum
    min = arr[0]; // Assume the first element as minimum

    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i]; // Update maximum if current element is greater
        } else if (arr[i] < min) {
            min = arr[i]; // Update minimum if current element is smaller
        }
    }
}

int main() {
    int arr[] = {3, 5, 8, 6, 10, 1};
    int size = sizeof(arr) / sizeof(arr[0]);

    int max, min;
    findMaxAndMin(arr, size, max, min);

    cout << "Maximum: " << max << endl;
    cout << "Minimum: " << min << endl;

    return 0;
}
