def extract_phone_numbers(string):
    sum = 0
    i = 0
    while i < len(string):
        if string[i].isdigit():
            i += 1
            continue
        if string[i:i+2] == "+1" or string[i:i+2] == "+4":
            phone_number = ""
            for j in range(i, i+14):
                if string[j].isdigit():
                    phone_number += string[j]
                elif string[j] == "-":
                    continue
                else:
                    break
            if len(phone_number) >= 7:
                sum += int(phone_number[-7:])
            i += 14
