  };

  const handleSortCriteriaChange = (e) => {
    const value = e.target.value;
    setSortCriteria(value);
  };

  const handleFilterChange = (filterType, value) => {
    setFilters((prevFilters) => ({
      ...prevFilters,
      [filterType]: value,
    }));
  };

  useEffect(() => {
    const debouncedSearch = setTimeout(() => {
      if (searchTerm.length >= 3) {
