        interestRateEditText = findViewById(R.id.interestRateEditText);
        loanDurationEditText = findViewById(R.id.loanDurationEditText);
        calculateButton = findViewById(R.id.calculateButton);
        resultTextView = findViewById(R.id.resultTextView);

        calculateButton.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                calculateMonthlyPayment();
            }
        });
    }

    private void calculateMonthlyPayment() {
        String loanAmountString = loanAmountEditText.getText().toString();
        String interestRateString = interestRateEditText.getText().toString();
        String loanDurationString = loanDurationEditText.getText().toString();

        if (loanAmountString.isEmpty() || interestRateString.isEmpty() || loanDurationString.isEmpty()) {
            resultTextView.setText("Please fill in all fields.");
            return;
        }

        float loanAmount = Float.parseFloat(loanAmountString);
        int interestRate = Integer.parseInt(interestRateString);
        int loanDuration = Integer.parseInt(loanDurationString);

        if (loanAmount <= 0 || interestRate < 0 || interestRate > 100 || loanDuration <= 0) {
            resultTextView.setText("Invalid input.");
            return;
        }

        float monthlyInterestRate = interestRate / 100.0f / 12;
        int loanDurationInMonths = loanDuration * 12;
        float monthlyPayment = (loanAmount * monthlyInterestRate) / (1 - (float) Math.pow(1 + monthlyInterestRate, -loanDurationInMonths));

        resultTextView.setText("Monthly Payment: " + monthlyPayment);
    }
}
