```java
import java.util.Scanner;

public class ArmstrongNumbers {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter the starting number: ");
        int start = scanner.nextInt();
        System.out.print("Enter the ending number: ");
        int end = scanner.nextInt();

        // Calculate the number of digits in the starting and ending numbers
        int startDigits = calculateDigits(start);
        int endDigits = calculateDigits(end);

        // Calculate the total number of Armstrong numbers within the given range
        int count = countArmstrongNumbers(start, end, startDigits, endDigits);

        // Display the Armstrong numbers in descending order
        displayArmstrongNumbers(start, end, count);
    }

    // Calculate the number of digits in a number using recursion
    public static int calculateDigits(int number) {
        if (number < 10) {
            return 1;
        } else {
            return 1 + calculateDigits(number / 10);
        }
    }

    // Calculate the total number of Armstrong numbers within the given range using recursion
    public static int countArmstrongNumbers(int current, int end, int startDigits, int endDigits) {
        if (current > end) {
            return 0;
        } else {
            int currentDigits = calculateDigits(current);

            if (current == calculateArmstrongSum(current, currentDigits)) {
                return 1 + countArmstrongNumbers(current + 1, end, startDigits, endDigits);
            } else {
                return countArmstrongNumbers(current + 1, end, startDigits, endDigits);
            }
        }
    }

    // Find and display the Armstrong numbers in descending order using recursion
    public static void displayArmstrongNumbers(int current, int end, int count) {
        if (current > end || count <= 0) {
            return;
        } else {
            int currentDigits = calculateDigits(current);

            if (current == calculateArmstrongSum(current, currentDigits)) {
                System.out.println(current);
                displayArmstrongNumbers(current + 1, end, count - 1);
            } else {
                displayArmstrongNumbers(current + 1, end, count);
            }
        }
    }

    // Calculate the Armstrong sum of a number using recursion
    public static int calculateArmstrongSum(int number, int digits) {
        if (number < 10) {
            return (int) Math.pow(number, digits);
        } else {
            int lastDigit = number % 10;
            return (int) Math.pow(lastDigit, digits) + calculateArmstrongSum(number / 10, digits);
        }
    }
}
```

This program prompts the user to enter the starting and ending numbers of the range. It then calculates the number of digits in the starting and ending numbers, and the total number of Armstrong numbers within the given range. Using recursion, it finds and displays the Armstrong numbers in descending order.

