Here is a C++ program that computes the weighted average of the given array elements and outputs the index of the maximum element in the array. It also handles the case where the array elements and weights are of different lengths and provides appropriate error handling.

```cpp
#include <iostream>
#include <vector>

double calculateWeightedAverage(const std::vector<int>& arr, const std::vector<double>& weights) {
    if (arr.size() != weights.size()) {
        throw std::invalid_argument("Array lengths do not match.");
    }

    double sum = 0;
    double weightSum = 0;
    for (size_t i = 0; i < arr.size(); i++) {
        sum += arr[i] * weights[i];
        weightSum += weights[i];
    }

    if (weightSum == 0) {
        throw std::invalid_argument("Weight sum is zero.");
    }

    return sum / weightSum;
}

int findMaxElementIndex(const std::vector<int>& arr) {
    if (arr.empty()) {
        throw std::invalid_argument("Array is empty.");
    }

    int maxElement = arr[0];
    int maxIndex = 0;
    for (size_t i = 1; i < arr.size(); i++) {
        if (arr[i] > maxElement) {
            maxElement = arr[i];
            maxIndex = i;
        }
    }

    return maxIndex;
}

int main() {
    std::vector<int> arr = {1, 2, 3, 4, 5, 6};
    std::vector<double> weights = {0.1, 0.2, 0.3, 0.2, 0.2};

    try {
        double weightedAverage = calculateWeightedAverage(arr, weights);
        int maxElementIndex = findMaxElementIndex(arr);

        std::cout << "Weighted Average: " << weightedAverage << std::endl;
        std::cout << "Max Element Index: " << maxElementIndex << std::endl;
    } catch (const std::invalid_argument& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
