Here is an implementation of the class Stack with the additional methods:

```cpp
#include <stack>
#include <unordered_map>

template<typename T>
class Stack {
private:
    std::stack<T> dataStack;
    std::stack<T> minStack;
    std::stack<T> maxStack;
    T sum;
    T product;
    T minimum;
    T maximum;
    T mode;
    T median;
    std::unordered_map<T, int> countMap;
    int maxCount;
    int size;
public:
    Stack() {
        sum = 0;
        product = 1;
        minimum = std::numeric_limits<T>::max();
        maximum = std::numeric_limits<T>::min();
        maxCount = 0;
        size = 0;
    }

    void push(T value) {
        dataStack.push(value);
        if (value < minimum) {
            minStack.push(value);
            minimum = value;
        } else {
            minStack.push(minimum);
        }
        if (value > maximum) {
            maxStack.push(value);
            maximum = value;
        } else {
            maxStack.push(maximum);
        }
        sum += value;
        product *= value;
        countMap[value]++;
        if (countMap[value] > maxCount) {
            maxCount = countMap[value];
            mode = value;
        }
        size++;
        updateMedian(value);
    }

    void pop() {
        if (size > 0) {
            dataStack.pop();
            minStack.pop();
            maxStack.pop();
            sum -= dataStack.top();
            product /= dataStack.top();
            countMap[dataStack.top()]--;
            if (dataStack.top() == mode) {
                maxCount--;
                if (maxCount == 0) {
                    updateMode();
                }
            }
            size--;
            updateMedian(dataStack.top());
        }
    }

    T getMinimum() {
        return minStack.top();
    }

    T getMaximum() {
        return maxStack.top();
    }

    T getAverage() {
        return sum / size;
    }

    T getMode() {
        return mode;
    }

    T getMedian() {
        return median;
    }

    T getSum() {
        return sum;
    }

    T getProduct() {
        return product;
    }

    T getRange() {
        return maximum - minimum;
    }

private:
    void updateMode() {
        for (auto& entry : countMap) {
            if (entry.second > maxCount) {
                maxCount = entry.second;
                mode = entry.first;
            }
        }
    }

    void updateMedian(T value) {
        if (size == 1) {
            median = value;
        } else if (size % 2 == 0) {
            if (value <= median) {
                median = (median * (size / 2) + value) / ((size / 2) + 1);
            } else {
                median = (median * (size / 2) + value) / (size / 2);
            }
        } else {
            if (value <= median) {
                median = (median * (size / 2) + value) / ((size / 2) + 1);
            } else {
                median = (median * (size / 2) + value) / (size / 2);
            }
        }
    }
};
```

This implementation uses three additional stacks: `minStack`, `maxStack`, and `dataStack`. The `minStack` keeps track of the minimum value at each position in the stack, the `maxStack` keeps track of the maximum value at each position, and the `dataStack` stores the actual data elements.

The `sum` variable keeps track of the sum of all elements, the `product` variable keeps track of the product of all elements, and the `countMap` is used to keep track of the count of each element.

The `mode` variable stores the mode (most frequently occurring element) and `maxCount` stores the count of the mode.

The `size` variable keeps track of the number of elements in the stack.

The `updateMedian` function is used to update the median whenever a new element is added or removed from the stack. The implementation of the `updateMode` function is straightforward.

The time complexity of all operations (push, pop, getMinimum, getMaximum, getAverage, getMode, getMedian, getSum, getProduct, getRange) is O(1) and the space complexity is O(n), where n is the number of elements in the stack.

Here's a Java implementation of the Bubble Sort algorithm that sorts an array of integers in ascending order. It also handles the case where the input array is empty and provides appropriate error handling:

```java
import java.util.Arrays;

public class BubbleSort {
    public static void main(String[] args) {
        int[] array = {}; // Empty array
        System.out.println("Before sorting: " + Arrays.toString(array));

        try {
            bubbleSort(array);
            System.out.println("After sorting: " + Arrays.toString(array));
        } catch (IllegalArgumentException e) {
            System.out.println("Error: " + e.getMessage());
        }
    }

    public static void bubbleSort(int[] array) {
        if (array.length == 0) {
            throw new IllegalArgumentException("Input array is empty");
        }

        boolean swapped;
        for (int i = 0; i < array.length - 1; i++) {
            swapped = false;
            for (int j = 0; j < array.length - 1 - i; j++) {
                if (array[j] > array[j + 1]) {
                    int temp = array[j];
                    array[j] = array[j + 1];
                    array[j + 1] = temp;
                    swapped = true;
                }
            }

            if (!swapped) {
                break;
            }
        }
    }
}
```

In this implementation, the `bubbleSort` method takes an array of integers as input and throws an `IllegalArgumentException` if the array is empty. The method then uses a nested loop to compare adjacent elements and swap them if they are in the wrong order. It repeats this process until the array is fully sorted or no more swaps are required.

