class Person:
    def __init__(self, name, age, street, city, state, zip_code):
        self.name = name
        self.age = age
        self.street = street
        self.city = city
        self.state = state
        self.zip_code = zip_code

def is_valid_string(string):
    return string.isalpha()

def is_valid_age(age):
    return isinstance(age, int) and age > 0

def is_valid_street(street):
    return street.isalnum()

def is_valid_zip_code(zip_code):
    return isinstance(zip_code, int) and len(str(zip_code)) == 5

def populate_person_details(person_details):
    tree = AVLTree()

    for person in person_details:
        name = person["name"]
        age = person["age"]
        street = person["street"]
        city = person["city"]
        state = person["state"]
        zip_code = person["zip_code"]

        if not is_valid_string(name):
            raise ValueError("Invalid name. Name should consist of only alphabetic characters.")

        if not is_valid_age(age):
            raise ValueError("Invalid age. Age should be a positive integer.")

        if not is_valid_street(street):
            raise ValueError("Invalid street. Street should be alphanumeric.")

        if not is_valid_string(city):
            raise ValueError("Invalid city name. City name should consist of only alphabetic characters.")

        if not is_valid_string(state):
            raise ValueError("Invalid state name. State name should consist of only alphabetic characters.")

        if not is_valid_zip_code(zip_code):
            raise ValueError("Invalid zip code. Zip code should be a 5-digit integer.")

        person_obj = Person(name, age, street, city, state, zip_code)
        tree.insert(person_obj)

    return tree
```

