import java.util.Scanner;

public class WordLengths {
    public static void main(String[] args) {
        // Read input from the user
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a sentence: ");
        String sentence = scanner.nextLine();

        // Remove punctuation marks from the sentence
        String cleanedSentence = sentence.replaceAll("[^a-zA-Z\\s]", "");

        // Split the sentence into words
        String[] words = cleanedSentence.split("\\s+");

        // Iterate over each word and print its length if it doesn't contain vowels
        for (String word : words) {
            if (!containsVowels(word)) {
                System.out.print(word.length() + " ");
            }
        }
    }

    // Helper method to check if a word contains vowels
    private static boolean containsVowels(String word) {
        String vowels = "aeiouAEIOU";
        for (char c : word.toCharArray()) {
            if (vowels.indexOf(c) != -1) {
                return true;
            }
        }
        return false;
    }
}
