import math

class Calculator:
    @staticmethod
    def add(a, b):
        Calculator._validate_positive_integer(a)
        Calculator._validate_positive_integer(b)
        return a + b

    @staticmethod
    def subtract(a, b):
        Calculator._validate_positive_integer(a)
        Calculator._validate_positive_integer(b)
        return a - b

    @staticmethod
    def multiply(a, b):
        Calculator._validate_positive_integer(a)
        Calculator._validate_positive_integer(b)
        return a * b

    @staticmethod
    def divide(a, b):
        Calculator._validate_positive_integer(a)
        Calculator._validate_positive_integer(b)
        if b == 0:
            raise ValueError("Cannot divide by zero")
        return a / b

    @staticmethod
    def square_root(a):
        Calculator._validate_positive_integer(a)
        return math.sqrt(a)

    @staticmethod
    def factorial(a):
        Calculator._validate_non_negative_integer(a)
        return math.factorial(a)

    @staticmethod
    def exponent(base, power):
        Calculator._validate_positive_integer(base)
        Calculator._validate_positive_integer(power)
        return base ** power

    @staticmethod
    def logarithm(number, base):
        Calculator._validate_positive_integer(number)
        Calculator._validate_positive_integer(base)
        if base <= 1:
            raise ValueError("Base must be greater than 1")
        return math.log(number, base)

    @staticmethod
    def absolute_value(a):
        if not isinstance(a, (int, float)):
            raise ValueError("Argument must be a number")
        return abs(a)

    @staticmethod
    def gcd(a, b):
        Calculator._validate_positive_integer(a)
        Calculator._validate_positive_integer(b)
        return math.gcd(a, b)

    @staticmethod
    def lcm(a, b):
        Calculator._validate_positive_integer(a)
        Calculator._validate_positive_integer(b)
        return a * b // math.gcd(a, b)

    @staticmethod
    def _validate_positive_integer(num):
        if not isinstance(num, int) or num <= 0:
            raise ValueError("Argument must be a positive integer")

    @staticmethod
    def _validate_non_negative_integer(num):
        if not isinstance(num, int) or num < 0:
            raise ValueError("Argument must be a non-negative integer")
```

