function findMostFrequentWords(input) {
  // List of common stop words to exclude
  const stopWords = ['the', 'and', 'is', 'a', 'of', 'in', 'to', 'it'];

  // Remove leading and trailing punctuation from each word
  const words = input.split(/\b/).map(word => word.replace(/^\W+|\W+$/g, ''));

  // Count the frequency of each word
  const wordCount = {};
  for (let word of words) {
    // Ignore case sensitivity
    word = word.toLowerCase();

    // Exclude stop words and empty strings
    if (word.length > 0 && !stopWords.includes(word)) {
      wordCount[word] = (wordCount[word] || 0) + 1;
    }
  }

  // Sort words by frequency (descending) and alphabetically (ascending)
  const sortedWords = Object.entries(wordCount).sort((a, b) => {
    const frequencyComparison = b[1] - a[1];
    if (frequencyComparison !== 0) {
      return frequencyComparison;
    } else {
      return a[0].localeCompare(b[0]);
    }
  });

  // Return array of most frequent words
  return sortedWords.map(entry => entry[0]);
}
```

