    void addCustomer(const Customer& customer) {
        if (customers.find(customer.email) != customers.end()) {
            std::cout << "Customer with email " << customer.email << " already exists!" << std::endl;
            return;
        }
        customers[customer.email] = customer;
        customerList.push_back(customer);
    }

    // Remove an existing customer from the set
    void removeCustomer(const std::string& email) {
        auto it = customers.find(email);
        if (it == customers.end()) {
            std::cout << "Customer with email " << email << " does not exist!" << std::endl;
            return;
        }
        customers.erase(it);
        for (auto iter = customerList.begin(); iter != customerList.end(); ++iter) {
            if (iter->email == email) {
                customerList.erase(iter);
                break;
            }
        }
    }

    // Update the information of an existing customer
    void updateCustomer(const Customer& customer) {
        auto it = customers.find(customer.email);
        if (it == customers.end()) {
            std::cout << "Customer with email " << customer.email << " does not exist!" << std::endl;
            return;
        }
        customers[customer.email] = customer;
