        auto it = customers.find(email);
        if (it == customers.end()) {
            std::cout << "Customer with email " << email << " does not exist!" << std::endl;
            return Customer();
        }
        return it->second;
    }

    // Find all customers within a specific age range
    std::vector<Customer> findCustomersInAgeRange(int minAge, int maxAge) {
        std::vector<Customer> result;
        for (const auto& customer : customerList) {
            if (customer.age >= minAge && customer.age <= maxAge) {
                result.push_back(customer);
            }
        }
        return result;
    }

    // Find all customers whose name starts with a given prefix
    std::vector<Customer> findCustomersWithNamePrefix(const std::string& prefix) {
        std::vector<Customer> result;
        for (const auto& customer : customerList) {
            if (customer.name.substr(0, prefix.length()) == prefix) {
