def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True


def find_primes(n):
    if not isinstance(n, int) or n <= 1:
        raise InvalidInputException("Input must be a positive integer greater than 1.")
    primes = []
    for num in range(2, n):
        if is_prime(num):
            primes.append(num)
    return primes
```

