Here is a React component that renders the provided state data in a table with the required features:

```jsx
import React, { useState } from 'react';

const Table = () => {
  const [data, setData] = useState([
    { id: 1, name: 'John', age: 20 },
    { id: 2, name: 'Alice', age: 18 }
  ]);

  const [selectedRows, setSelectedRows] = useState([]);
  const [editingRow, setEditingRow] = useState(null);

  const handleCheckboxChange = (event, id) => {
    const isChecked = event.target.checked;
    if (isChecked) {
      setSelectedRows([...selectedRows, id]);
    } else {
      setSelectedRows(selectedRows.filter(rowId => rowId !== id));
    }
  };

  const handleDeleteSelectedRows = () => {
    const updatedData = data.filter(row => !selectedRows.includes(row.id));
    setData(updatedData);
    setSelectedRows([]);
  };

  const handleAddRow = () => {
    const newRow = { id: data.length + 1, name: '', age: '' };
    setData([...data, newRow]);
  };

  const handleEditRow = (id) => {
    setEditingRow(id);
  };

  const handleSaveRow = (id, newData) => {
    const updatedData = data.map(row => {
      if (row.id === id) {
        return { ...row, ...newData };
      }
      return row;
    });
    setData(updatedData);
    setEditingRow(null);
  };

  return (
    <div>
      <button onClick={handleDeleteSelectedRows}>Delete Selected Rows</button>
      <table>
        <thead>
          <tr>
            <th>Select</th>
            <th>ID</th>
            <th>Name</th>
            <th>Age</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {data.map(row => (
            <TableRow
              key={row.id}
              row={row}
              isSelected={selectedRows.includes(row.id)}
              isEditing={editingRow === row.id}
              onCheckboxChange={handleCheckboxChange}
              onEdit={handleEditRow}
              onSave={handleSaveRow}
            />
          ))}
        </tbody>
      </table>
      <button onClick={handleAddRow}>Add New Row</button>
    </div>
  );
};

const TableRow = ({ row, isSelected, isEditing, onCheckboxChange, onEdit, onSave }) => {
  const [name, setName] = useState(row.name);
  const [age, setAge] = useState(row.age);

  const handleNameChange = (event) => {
    setName(event.target.value);
  };

  const handleAgeChange = (event) => {
    setAge(event.target.value);
  };

  const handleSaveClick = () => {
    onSave(row.id, { name, age });
  };

  if (isEditing) {
    return (
      <tr>
        <td>
          <input type="checkbox" checked={isSelected} onChange={(event) => onCheckboxChange(event, row.id)} />
        </td>
        <td>{row.id}</td>
        <td>
          <input type="text" value={name} onChange={handleNameChange} />
        </td>
        <td>
          <input type="text" value={age} onChange={handleAgeChange} />
        </td>
        <td>
          <button onClick={handleSaveClick}>Save</button>
        </td>
      </tr>
    );
  }

  return (
