```java
public class ComplexNumber {
    private double real;
    private double imaginary;

    public ComplexNumber(double real, double imaginary) {
        this.real = real;
        this.imaginary = imaginary;
    }

    public double getReal() {
        return real;
    }

    public double getImaginary() {
        return imaginary;
    }

    public double getMagnitude() {
        return Math.sqrt(real * real + imaginary * imaginary);
    }

    public double getPhase() {
        return Math.atan2(imaginary, real);
    }

    public ComplexNumber getConjugate() {
        return new ComplexNumber(real, -imaginary);
    }

    public ComplexNumber add(ComplexNumber other) {
        double newReal = real + other.getReal();
        double newImaginary = imaginary + other.getImaginary();
        return new ComplexNumber(newReal, newImaginary);
    }

    public ComplexNumber subtract(ComplexNumber other) {
        double newReal = real - other.getReal();
        double newImaginary = imaginary - other.getImaginary();
        return new ComplexNumber(newReal, newImaginary);
    }

    public ComplexNumber multiply(ComplexNumber other) {
        double newReal = real * other.getReal() - imaginary * other.getImaginary();
        double newImaginary = real * other.getImaginary() + imaginary * other.getReal();
        return new ComplexNumber(newReal, newImaginary);
    }

    public ComplexNumber divide(ComplexNumber other) {
        double denominator = other.getReal() * other.getReal() + other.getImaginary() * other.getImaginary();
        double newReal = (real * other.getReal() + imaginary * other.getImaginary()) / denominator;
        double newImaginary = (imaginary * other.getReal() - real * other.getImaginary()) / denominator;
        return new ComplexNumber(newReal, newImaginary);
    }

    public boolean isEqual(ComplexNumber other) {
        return real == other.getReal() && imaginary == other.getImaginary();
    }

    public int compareMagnitude(ComplexNumber other) {
        double magnitude = getMagnitude();
        double otherMagnitude = other.getMagnitude();
        if (magnitude < otherMagnitude) {
            return -1;
        } else if (magnitude > otherMagnitude) {
            return 1;
        } else {
            return 0;
        }
    }

    public boolean isPureImaginary() {
        return real == 0 && imaginary != 0;
    }

    public boolean isPureReal() {
        return imaginary == 0 && real != 0;
    }
}
