```java
import java.util.Arrays;

public class CommonElementsFinder {
    public static void main(String[] args) {
        int[] array1 = { 2, 4, 8, 9, 12, 15 };
        int[] array2 = { 3, 4, 7, 9, 12, 17, 19 };

        int[] commonElements = findCommonElements(array1, array2);

        System.out.println("Common elements: " + Arrays.toString(commonElements));
    }

    public static int[] findCommonElements(int[] array1, int[] array2) {
        Arrays.sort(array1); // Sort array1 in ascending order
        Arrays.sort(array2); // Sort array2 in ascending order

        int[] commonElements = new int[Math.min(array1.length, array2.length)];
        int index1 = 0; // Pointer for array1
        int index2 = 0; // Pointer for array2
        int commonIndex = 0; // Index for commonElements array

        while (index1 < array1.length && index2 < array2.length) {
            if (array1[index1] == array2[index2]) {
                commonElements[commonIndex] = array1[index1];
                commonIndex++;
                index1++;
                index2++;
            } else if (array1[index1] < array2[index2]) {
                index1++;
            } else {
                index2++;
            }
        }

        return Arrays.copyOf(commonElements, commonIndex);
    }
}
