```perl
#!/usr/bin/perl

use strict;
use warnings;

# Set the valid top-level domains
my @valid_domains = qw(com net org edu gov);

# Hash to store domain occurrences
my %domain_counts;

# Open the input file
open(my $fh, "<", "input.txt") or die "Cannot open file: $!";

# Read the file line by line
while (my $line = <$fh>) {
    # Extract email addresses using regex
    my @matches = $line =~ /(\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b)/g;

    # Process each matched email address
    foreach my $email (@matches) {
        # Extract domain from the email address
        my ($domain) = $email =~ /@([A-Za-z0-9.-]+\.[A-Za-z]{2,})$/;

        # Exclude email addresses with subdomains
        next if $domain =~ /\./;

        # Check if domain is valid
        next unless grep { $domain eq $_ } @valid_domains;

        # Count the domain occurrence
        $domain_counts{$domain}++;
    }
}

# Close the input file
close($fh);

# Sort the domain counts in descending order
my @sorted_domains = sort { $domain_counts{$b} <=> $domain_counts{$a} } keys %domain_counts;

# Display the top 10 domains with the highest occurrences
my $count = 0;
foreach my $domain (@sorted_domains) {
    last if $count >= 10;
    print "$domain: $domain_counts{$domain}\n";
    $count++;
}
```

