Here is an implementation of a basic url parser in JavaScript that can return the path and query parameters from a given url:

```javascript
function parseUrl(url) {
  const result = {
    protocol: "",
    domain: "",
    port: "",
    path: "",
    queryParams: {}
  };

  // Check if the url is empty or null
  if (!url) {
    return result;
  }

  // Split the url into different parts
  const parts = url.split("://");

  // Check if the url has a protocol
  if (parts.length > 1) {
    result.protocol = parts[0];
    url = parts[1];
  }

  // Split the url into domain and path
  const domainParts = url.split("/");
  result.domain = domainParts[0];

  // Check if the domain has a port
  const portIndex = result.domain.indexOf(":");
  if (portIndex !== -1) {
    result.port = result.domain.slice(portIndex + 1);
    result.domain = result.domain.slice(0, portIndex);
  }

  // Check if the url has a path
  if (domainParts.length > 1) {
    result.path = `/${domainParts.slice(1).join("/")}`;
  }

  // Check if the url has query parameters
  const queryIndex = url.indexOf("?");
  if (queryIndex !== -1) {
    const queryString = url.slice(queryIndex + 1);
    const queryParams = queryString.split("&");
    for (const param of queryParams) {
      const [key, value] = param.split("=");
      result.queryParams[key] = value;
    }
  }

  return result;
}

// Example usage
const url = "http://example.com:8080/path/to/resource?param1=value1&param2=value2";
