void generatePrimesLessThan(int num, int primes[], int* numPrimes) {
    *numPrimes = 0;

    for (int i = 2; i < num; i++) {
        if (isPrime(i))
            primes[(*numPrimes)++] = i;
    }
}

void generatePrimesGreaterThan(int num, int primes[], int* numPrimes) {
    *numPrimes = 0;

    for (int i = num + 1; ; i++) {
        if (isPrime(i)) {
            primes[(*numPrimes)++] = i;
            break;
        }
    }
}

