```python
import tensorflow as tf
import numpy as np
import random

# Step 1: Initialize a population of potential solutions
def initialize_population(population_size, nn_architecture):
    population = []
    for _ in range(population_size):
        solution = {}
        for layer, size in enumerate(nn_architecture):
            if layer > 0:
                input_size = nn_architecture[layer - 1]
                output_size = nn_architecture[layer]
                weights = np.random.randn(input_size, output_size)
                biases = np.random.randn(output_size)
                solution[(layer, "weights")] = weights
                solution[(layer, "biases")] = biases
        population.append(solution)
    return population

# Step 2: Evaluate the fitness of each solution
def evaluate_fitness(solution, dataset):
    # Build and train the neural network
    model = build_model(solution)
    model.compile(optimizer='adam', loss='binary_crossentropy', metrics=['accuracy'])
    model.fit(dataset["inputs"], dataset["labels"], epochs=10, batch_size=32)

    # Evaluate the fitness score
    _, accuracy = model.evaluate(dataset["inputs"], dataset["labels"])
    return accuracy

# Helper function to build the neural network model
def build_model(solution):
    model = tf.keras.Sequential()
    for layer in sorted(solution.keys()):
        if "weights" in layer:
            model.add(tf.keras.layers.Dense(solution[layer].shape[1], activation='relu'))
        elif "biases" in layer:
            model.add(tf.keras.layers.Dense(solution[layer].shape[0]))
    return model

# Step 3: Select the fittest solutions
def select_fittest(population, dataset, fittest_ratio):
    fittest_size = int(len(population) * fittest_ratio)
    fittest_population = []
    for solution in population:
        fitness = evaluate_fitness(solution, dataset)
        fittest_population.append((solution, fitness))
    fittest_population.sort(key=lambda x: x[1], reverse=True)
    return [solution for solution, _ in fittest_population[:fittest_size]]

# Step 4: Apply genetic operators to create offspring solutions
def crossover(parent1, parent2):
    offspring = {}
    for layer in parent1.keys():
        if random.random() < 0.5:
            offspring[layer] = parent1[layer]
        else:
            offspring[layer] = parent2[layer]
    return offspring

def mutate(solution, mutation_rate):
    mutated_solution = {}
    for layer in solution.keys():
        if random.random() < mutation_rate:
            if "weights" in layer:
                mutated_solution[layer] = solution[layer] + np.random.randn(*solution[layer].shape)
            elif "biases" in layer:
                mutated_solution[layer] = solution[layer] + np.random.randn(*solution[layer].shape)
        else:
            mutated_solution[layer] = solution[layer]
    return mutated_solution

# Step 5: Main optimization loop
def optimize_nn(population_size, nn_architecture, dataset, fittest_ratio, crossover_rate, mutation_rate, max_generations, fitness_threshold):
    population = initialize_population(population_size, nn_architecture)
    best_fitness = 0.0
    best_solution = None

    for generation in range(max_generations):
        fittest_population = select_fittest(population, dataset, fittest_ratio)
        if fittest_population[0][1] > best_fitness:
            best_fitness = fittest_population[0][1]
            best_solution = fittest_population[0][0]
        population = [best_solution] + fittest_population

        while len(population) < population_size:
            parent1 = random.choice(fittest_population)
            parent2 = random.choice(fittest_population)
            offspring = crossover(parent1, parent2)
            mutated_offspring = mutate(offspring, mutation_rate)
            population.append(mutated_offspring)

        if best_fitness >= fitness_threshold:
            break

    return best_solution, best_fitness, generation + 1

# Step 6: Elitism and Step 7: Adaptive mutation are already implemented in the main loop

# Step 8: Output the best solution found
nn_architecture = [10, 5, 1]  # Example architecture: 10 input units, 5 hidden units, 1 output unit
dataset = {"inputs": np.random.randn(10000, 10), "labels": np.random.randint(2, size=(10000, 1))}
best_solution, best_fitness, num_generations = optimize_nn(1000, nn_architecture, dataset, 0.2, 0.8, 0.05, 500, 0.9)
print("Best solution:", best_solution)
print("Best fitness:", best_fitness)
print("Number of generations:", num_generations)
