Webhooks are a way for server-side applications to receive real-time notifications or data updates from external services. They allow these services to send HTTP POST requests to a predefined endpoint in your application, providing you with instant updates without the need for polling or constantly checking for new data.

Here is an example of how webhooks can be implemented in a server-side application using the Node.js programming language:

```javascript
const express = require('express');
const crypto = require('crypto');
const app = express();

// Secret key used for encryption and decryption
const SECRET_KEY = 'your_secret_key';

// Endpoint to receive webhook notifications
app.post('/webhook', (req, res) => {
  const payload = req.body;
  const signature = req.headers['x-signature'];

  // Verify the integrity of the payload using the signature
  if (verifySignature(payload, signature)) {
    // Process the payload data
    console.log('Received webhook payload:', payload);

    // Respond with a success status
    res.sendStatus(200);
  } else {
    // Signature verification failed, reject the payload
    console.error('Webhook payload signature verification failed');
    res.sendStatus(400);
  }
});

// Function to verify the payload signature
function verifySignature(payload, signature) {
  const hmac = crypto.createHmac('sha256', SECRET_KEY);
  const computedSignature = hmac.update(JSON.stringify(payload)).digest('hex');
  return signature === computedSignature;
}

// Start the server
app.listen(3000, () => {
  console.log('Server listening on port 3000');
});
```

In this example, we use the Express framework to create a simple server that listens for POST requests on the `/webhook` endpoint. The received payload is then verified using a signature passed in the request headers. The `verifySignature` function takes the payload, computes a signature using a secret key, and compares it with the received signature to ensure the payload integrity.

To transmit the webhook payload securely, you can use encryption. One way to achieve this is by encrypting the payload using a shared secret key before sending it and decrypting it on the server-side using the same secret key.

Here's an updated example that includes encryption:

```javascript
const express = require('express');
const crypto = require('crypto');
const app = express();

// Secret key used for encryption and decryption
const SECRET_KEY = 'your_secret_key';

// Endpoint to receive webhook notifications
app.post('/webhook', (req, res) => {
  const encryptedPayload = req.body.payload;
  const signature = req.headers['x-signature'];

  // Decrypt the payload using the secret key
  const decryptedPayload = decryptPayload(encryptedPayload);

  // Verify the integrity of the payload using the signature
  if (verifySignature(decryptedPayload, signature)) {
    // Process the decrypted payload data
    console.log('Received webhook payload:', decryptedPayload);

    // Respond with a success status
    res.sendStatus(200);
  } else {
    // Signature verification failed, reject the payload
    console.error('Webhook payload signature verification failed');
    res.sendStatus(400);
  }
});

// Function to decrypt the encrypted payload
function decryptPayload(encryptedPayload) {
  const decipher = crypto.createDecipher('aes256', SECRET_KEY);
  let decrypted = decipher.update(encryptedPayload, 'hex', 'utf-8');
  decrypted += decipher.final('utf-8');
  return JSON.parse(decrypted);
}

// Function to verify the payload signature
function verifySignature(payload, signature) {
  const hmac = crypto.createHmac('sha256', SECRET_KEY);
  const computedSignature = hmac.update(JSON.stringify(payload)).digest('hex');
  return signature === computedSignature;
}

// Start the server
app.listen(3000, () => {
  console.log('Server listening on port 3000');
});
```

In this updated example, the webhook payload is encrypted on the sender's side before sending it to your application. On the server-side, the encrypted payload is decrypted using the same secret key before further processing and signature verification.

Please note that this example is simplified for demonstration purposes, and in a production environment, you should consider additional security measures and follow best practices for encryption, secret management, and signature verification.

