    this.bookList.sort((a, b) => a.name.localeCompare(b.name));
  }

  filterBooksByAuthor() {
    this.filteredBooks = this.bookList.filter(book => book.author.toLowerCase().includes(this.searchTerm.toLowerCase()));
    this.currentPage = 0; // Reset current page when applying filter
  }

  addBook(bookName: string, authorName: string) {
    const newBook = { name: bookName, author: authorName };
    this.bookList.push(newBook);
    this.filterBooksByAuthor(); // Reapply the filter after adding a book
  }

  deleteBook(index: number) {
    this.bookList.splice(index, 1);
    this.filterBooksByAuthor(); // Reapply the filter after deleting a book
  }

  getPaginatedBooks() {
    const startIndex = this.currentPage * this.booksPerPage;
    const endIndex = startIndex + this.booksPerPage;
    return this.filteredBooks.slice(startIndex, endIndex);
  }

  goToPreviousPage() {
    if (this.currentPage > 0) {
      this.currentPage--;
    }
  }

  goToNextPage() {
    const maxPage = Math.ceil(this.filteredBooks.length / this.booksPerPage) - 1;
    if (this.currentPage < maxPage) {
      this.currentPage++;
    }
  }
}
