Here is a possible implementation of a quickly-sortable tree in Python:

```python
class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

class QuickSortTree:
    def __init__(self):
        self.root = None

    def insert(self, value):
        if self.root is None:
            self.root = Node(value)
        else:
            self._insert_recursive(self.root, value)

    def _insert_recursive(self, node, value):
        if value < node.value:
            if node.left is None:
                node.left = Node(value)
            else:
                self._insert_recursive(node.left, value)
        else:
            if node.right is None:
                node.right = Node(value)
            else:
                self._insert_recursive(node.right, value)

    def sort(self, array):
        if not array:
            return []
        self.root = None
        self._sort_recursive(array, 0, len(array) - 1)

    def _sort_recursive(self, array, low, high):
        if low < high:
            pivot_index = self._partition(array, low, high)
            self._sort_recursive(array, low, pivot_index - 1)
            self._sort_recursive(array, pivot_index + 1, high)

    def _partition(self, array, low, high):
        pivot = array[high]
        i = low - 1
        for j in range(low, high):
            if array[j] < pivot:
                i += 1
                array[i], array[j] = array[j], array[i]
        array[i + 1], array[high] = array[high], array[i + 1]
        return i + 1

    def in_order_traversal(self):
        if self.root is None:
            return []
        return self._in_order_traversal_recursive(self.root)

    def _in_order_traversal_recursive(self, node):
        result = []
        if node.left:
            result += self._in_order_traversal_recursive(node.left)
        result.append(node.value)
        if node.right:
            result += self._in_order_traversal_recursive(node.right)
        return result
```

