```cpp
#include <iostream>
#include <string>

using namespace std;

string getGCF(string a, string b) {
    if (b == "0") {
        return a;
    }

    return getGCF(b, to_string(stoll(a) % stoll(b)));
}

int main() {
    string a, b;

    cout << "Enter the first number: ";
    cin >> a;

    cout << "Enter the second number: ";
