```cpp
#include <iostream>
#include <string>

using namespace std;

int countParameters(string declaration) {
    int count = 0;
    int nestedCount = 0;
    bool isNested = false;
    bool isInsideFunction = false;

    for (char c : declaration) {
        if (c == '(') {
            isInsideFunction = true;
            if (isNested) {
                nestedCount++;
            }
        }
        else if (c == ')') {
            isInsideFunction = false;
            if (isNested) {
                isNested = false;
                count += nestedCount;
                nestedCount = 0;
            }
        }
        else if (isInsideFunction && !isNested && c == ',') {
            count++;
        }
        else if (isInsideFunction && c == '{') {
            isNested = true;
        }
    }

    return count;
}

int main() {
    string declaration;
    cout << "Enter function declaration: ";
    getline(cin, declaration);

    int parameterCount = countParameters(declaration);
    cout << "Total number of parameters: " << parameterCount << endl;

    return 0;
}
