Here is an implementation of the Fibonacci Heap class that supports the requested operations with the desired time complexities:

```python
class FibonacciHeapNode:
    def __init__(self, key):
        self.key = key
        self.degree = 0
        self.marked = False
        self.parent = None
        self.child = None
        self.left = self
        self.right = self

class FibonacciHeap:
    def __init__(self):
        self.min_node = None
        self.num_nodes = 0

    def insert(self, key):
        new_node = FibonacciHeapNode(key)
        if self.min_node is None:
            self.min_node = new_node
        else:
            new_node.left = self.min_node
            new_node.right = self.min_node.right
            self.min_node.right = new_node
            new_node.right.left = new_node
            if key < self.min_node.key:
                self.min_node = new_node
        self.num_nodes += 1

    def extract_min(self):
        min_node = self.min_node
        if min_node is not None:
            if min_node.child is not None:
                child = min_node.child
                while True:
                    child.parent = None
                    child = child.right
                    if child == min_node.child:
                        break
            min_node.left.right = min_node.right
            min_node.right.left = min_node.left
            if min_node == min_node.right:
                self.min_node = None
            else:
                self.min_node = min_node.right
                self.consolidate()
            self.num_nodes -= 1
        return min_node.key

    def consolidate(self):
        degree_table = [None] * (self.num_nodes.bit_length() + 1)
        nodes = []
        curr = self.min_node
        while True:
            nodes.append(curr)
            curr = curr.right
            if curr == self.min_node:
                break
        for node in nodes:
            degree = node.degree
            while degree_table[degree] is not None:
                other = degree_table[degree]
                if node.key > other.key:
                    node, other = other, node
                self.link(other, node)
                degree_table[degree] = None
                degree += 1
            degree_table[degree] = node
            if node.key <= self.min_node.key:
                self.min_node = node

    def link(self, child, parent):
        child.left.right = child.right
        child.right.left = child.left
        child.parent = parent
        if parent.child is None:
            parent.child = child
            child.right = child
            child.left = child
        else:
            child.left = parent.child
            child.right = parent.child.right
            parent.child.right = child
            child.right.left = child
        parent.degree += 1
        child.marked = False

    def decrease_key(self, node, new_key):
        if new_key > node.key:
            return
        node.key = new_key
        parent = node.parent
        if parent is not None and node.key < parent.key:
            self.cut(node, parent)
            self.cascading_cut(parent)
        if node.key < self.min_node.key:
            self.min_node = node

    def cut(self, child, parent):
        child.left.right = child.right
        child.right.left = child.left
        parent.degree -= 1
        if parent.child == child:
            parent.child = child.right
        if parent.degree == 0:
            parent.child = None
        child.left = self.min_node
        child.right = self.min_node.right
        self.min_node.right = child
        child.right.left = child
        child.parent = None
        child.marked = False

    def cascading_cut(self, node):
        parent = node.parent
        if parent is not None:
            if not node.marked:
                node.marked = True
            else:
                self.cut(node, parent)
                self.cascading_cut(parent)

    def merge(self, other_heap):
        if self.min_node is None:
            self.min_node = other_heap.min_node
        elif other_heap.min_node is not None:
            self.min_node.right.left = other_heap.min_node.left
            other_heap.min_node.left.right = self.min_node.right
            self.min_node.right = other_heap.min_node
            other_heap.min_node.left = self.min_node
            if other_heap.min_node.key < self.min_node.key:
                self.min_node = other_heap.min_node
        self.num_nodes += other_heap.num_nodes

    def delete(self, node):
        self.decrease_key(node, float('-inf'))
        self.extract_min()

    def find_min(self):
        return self.min_node.key
```

Note that this implementation assumes that all keys inserted into the Fibonacci Heap are unique. If you need to handle duplicate keys, you may need to modify the code accordingly.

