```javascript
function base64Encode(str) {
  let encoded = '';
  let prevChar = '';
  let count = 0;

  for (let i = str.length - 1; i >= 0; i--) {
    const char = str[i];
    const ascii = char.charCodeAt(0).toString(16);

    if (char === prevChar) {
      count++;
    } else {
      if (count > 0) {
        encoded += `$${count}`;
      }
      encoded += ascii;
      count = 1;
      prevChar = char;
    }
  }

  encoded += `$${count}`;
  return encoded;
}
