            for product in self.products[category][manufacturer].values():
                quantity += product.quantity
            return quantity
        return 0

    def get_total_value(self, category, manufacturer):
        if category in self.products and manufacturer in self.products[category]:
            total_value = 0
            for product in self.products[category][manufacturer].values():
                total_value += product.price * product.quantity
            return total_value
        return 0

    def search_products(self, name=None, category=None, manufacturer=None):
        results = []
        for category in self.products:
            for manufacturer in self.products[category]:
                for product in self.products[category][manufacturer].values():
                    if (name is None or product.name == name) and \
                       (category is None or product.category == category) and \
                       (manufacturer is None or product.manufacturer == manufacturer):
                        results.append(product)
        return results

    def sort_products(self, field, ascending=True):
        for category in self.products:
            for manufacturer in self.products[category]:
                self.products[category][manufacturer] = sorted(
                    self.products[category][manufacturer].values(),
                    key=lambda product: getattr(product, field),
                    reverse=not ascending
