#include <stdio.h>

void printBinary(int num) {
    if (num == 0) {
        printf("0");
        return;
    }

    int size = sizeof(num) * 8;  // Number of bits in an integer

    // Iterate through each bit from left to right
    for (int i = size - 1; i >= 0; i--) {
        int bit = (num >> i) & 1;  // Extract i-th bit using bitwise right shift and bitwise AND

