function findSecondSmallest(arr) {
  // Remove duplicates from the array
  const distinctArr = Array.from(new Set(arr));

  // Sort the distinct array in ascending order
  const sortedArr = distinctArr.sort((a, b) => a - b);

  // Check if there are at least two distinct numbers
  if (sortedArr.length < 2) {
    return undefined;
  }

  // Return the second smallest distinct number
  return sortedArr[1];
}
