```java
import java.util.Scanner;

public class StarPattern {
    public static void main(String[] args) {
        int numRows = getValidNumRows();

        printStarPattern(numRows);
    }

    private static int getValidNumRows() {
        Scanner scanner = new Scanner(System.in);
        int numRows;
        do {
            System.out.print("Enter the number of rows (between 5 and 15, odd number only): ");
            numRows = scanner.nextInt();
            if (numRows < 5 || numRows > 15) {
                System.out.println("Invalid input. Please enter a number between 5 and 15.");
            } else if (numRows % 2 == 0) {
                System.out.println("Invalid input. Please enter an odd number of rows.");
            } else {
                return numRows;
            }
        } while (true);
    }

    private static void printStarPattern(int numRows) {
        int numSpaces = numRows / 2;
        int numStars = 1;

        for (int i = 0; i < numRows; i++) {
            for (int j = 0; j < numSpaces; j++) {
                System.out.print(" ");
            }

            for (int j = 0; j < numStars; j++) {
                System.out.print("*");
            }

            System.out.println();

            if (i < numRows / 2) {
                numSpaces--;
                numStars += 2;
            } else {
                numSpaces++;
                numStars -= 2;
            }
        }
    }
}
