def sort_list_of_tuples(list_of_tuples):
    # Sort based on second element in each tuple
    for i in range(len(list_of_tuples)):
        for j in range(i+1, len(list_of_tuples)):
            if list_of_tuples[i][1] > list_of_tuples[j][1]:
                list_of_tuples[i], list_of_tuples[j] = list_of_tuples[j], list_of_tuples[i]
            elif list_of_tuples[i][1] == list_of_tuples[j][1]:
                # Sort in descending order based on first element if second elements are equal
                if list_of_tuples[i][0] < list_of_tuples[j][0]:
                    list_of_tuples[i], list_of_tuples[j] = list_of_tuples[j], list_of_tuples[i]
                elif list_of_tuples[i][0] == list_of_tuples[j][0]:
                    # Sort in ascending order based on length of first element if both elements are equal
                    if len(list_of_tuples[i][0]) > len(list_of_tuples[j][0]):
                        list_of_tuples[i], list_of_tuples[j] = list_of_tuples[j], list_of_tuples[i]
    return list_of_tuples

