#define MAX_NAME_LENGTH 50
#define MAX_ID_LENGTH 8

typedef struct {
    char name[MAX_NAME_LENGTH];
    int age;
    char id[MAX_ID_LENGTH];
    float gpa;
} Student;

bool validateID(char id[]) {
    if (strlen(id) != 7 || id[0] != 'S')
        return false;

    for (int i = 1; i < 7; i++) {
        if (id[i] < '0' || id[i] > '9')
            return false;
    }

    if (id[1] == '0')
        return false;

    return true;
}

void displayStudentDetails(Student student) {
    if (strlen(student.name) == 0) {
        printf("Invalid name\n");
    } else if (student.age < 18 || student.age > 25) {
        printf("Invalid age\n");
    } else if (!validateID(student.id)) {
        printf("Invalid ID\n");
    } else if (student.gpa < 0.0 || student.gpa > 4.0) {
        printf("Invalid GPA\n");
    } else {
        printf("Name: %s\n", student.name);
        printf("Age: %d\n", student.age);
        printf("ID: %s\n", student.id);
        printf("GPA: %.2f\n", student.gpa);
    }
}

float calculateAverageGPA(Student students[], int numStudents) {
    float totalGPA = 0.0;

    for (int i = 0; i < numStudents; i++) {
        if (validateID(students[i].id))
            totalGPA += students[i].gpa;
    }

    return totalGPA / numStudents;
}

void sortStudentsByGPA(Student students[], int numStudents) {
    Student temp;

    for (int i = 0; i < numStudents - 1; i++) {
        for (int j = 0; j < numStudents - i - 1; j++) {
            if (students[j].gpa < students[j + 1].gpa) {
                temp = students[j];
                students[j] = students[j + 1];
                students[j + 1] = temp;
            }
        }
    }
}

