Here is a solution that groups the objects of an array into bunches of 3, sorts each bunch in ascending order, and returns the output array sorted in descending order based on the sum of the objects in each bunch:

```javascript
function groupObjectsIntoBunches(arr) {
  // Group objects into bunches of 3
  const bunches = [];
  for (let i = 0; i < arr.length; i += 3) {
    const bunch = arr.slice(i, i + 3);
    bunch.sort((a, b) => a - b);
    bunches.push(bunch);
  }

  // Sort bunches in descending order based on sum
  bunches.sort((a, b) => {
    const sumA = a.reduce((acc, val) => acc + val, 0);
    const sumB = b.reduce((acc, val) => acc + val, 0);
    return sumB - sumA;
  });

  return bunches;
}

