void sortDescendingAndExcludePrimes(std::vector<int>& arr) {
    // Sort the array in descending order
    std::sort(arr.begin(), arr.end(), std::greater<int>());

    // Exclude prime numbers from the sorted array
    arr.erase(std::remove_if(arr.begin(), arr.end(), isPrime), arr.end());
}

