```java
import java.util.Scanner;

public class IntegerToRoman {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        System.out.print("Enter an integer within the range of -5000 to 5000: ");
        int num = input.nextInt();
        input.close();

        if (num < -5000 || num > 5000) {
            System.out.println("Invalid input! The number must be within the range of -5000 to 5000.");
            return;
        }

        String romanNum = toRoman(num);
        System.out.println("The Roman numeral representation of " + num + " is: " + romanNum);
    }

    public static String toRoman(int num) {
        String[] thousands = {"", "M", "MM", "MMM", "MMMM"};
        String[] hundreds = {"", "C", "CC", "CCC", "CD", "D", "DC", "DCC", "DCCC", "CM"};
        String[] tens = {"", "X", "XX", "XXX", "XL", "L", "LX", "LXX", "LXXX", "XC"};
        String[] units = {"", "I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX"};

        StringBuilder roman = new StringBuilder();

        // Handling negative numbers
        if (num < 0) {
            roman.append("-");
            num = -num;
        }

        // Adding thousands place value
        roman.append(thousands[num / 1000]);
        num %= 1000;

        // Adding hundreds place value
        roman.append(hundreds[num / 100]);
        num %= 100;

        // Adding tens place value
        roman.append(tens[num / 10]);
        num %= 10;

        // Adding units place value
        roman.append(units[num]);

        return roman.toString();
    }
}
