Here's a Java code that clones a linked list using recursion and implements a method to reverse the cloned linked list using a doubly linked list:

```java
class Node {
    Object data;
    Node next;
    Node prev;

    public Node(Object data) {
        this.data = data;
        this.next = null;
        this.prev = null;
    }
}

class LinkedList {
    private Node head;

    public LinkedList() {
        this.head = null;
    }

    public void insert(Object data) {
        Node newNode = new Node(data);
        if (head == null) {
            head = newNode;
        } else {
            Node currentNode = head;
            while (currentNode.next != null) {
                currentNode = currentNode.next;
            }
            currentNode.next = newNode;
            newNode.prev = currentNode;
        }
    }

    public LinkedList clone() {
        LinkedList clonedList = new LinkedList();
        if (head != null) {
            cloneRecursively(clonedList, head);
        }
        return clonedList;
    }

    private void cloneRecursively(LinkedList clonedList, Node node) {
        if (node != null) {
            clonedList.insert(node.data);
            cloneRecursively(clonedList, node.next);
        }
    }

    public void reverse() {
        if (head != null) {
            Node currentNode = head;
            Node tempNode = null;
            while (currentNode != null) {
                tempNode = currentNode.prev;
                currentNode.prev = currentNode.next;
                currentNode.next = tempNode;
                currentNode = currentNode.prev;
            }
            if (tempNode != null) {
                head = tempNode.prev;
            }
        }
    }

    public void display() {
        Node currentNode = head;
        while (currentNode != null) {
            System.out.print(currentNode.data + " ");
            currentNode = currentNode.next;
        }
        System.out.println();
    }
}

public class Main {
    public static void main(String[] args) {
        LinkedList originalList = new LinkedList();
        originalList.insert(1);
        originalList.insert("Hello");
        originalList.insert(3);
        originalList.insert("World");

        System.out.print("Original List: ");
        originalList.display();

        LinkedList clonedList = originalList.clone();
        System.out.print("Cloned List: ");
