        'password': 'userpassword',
        'role': 'user'
    }
}

# Decorator for user authentication and authorization
def login_required(role='user'):
    def wrapper(fn):
        @wraps(fn)
        def decorated_view(*args, **kwargs):
            if 'username' not in session or users[session['username']]['role'] != role:
                return redirect(url_for('login'))
            return fn(*args, **kwargs)
        return decorated_view
    return wrapper

# Home page with search form
@app.route('/')
@login_required()
def index():
    return render_template('index.html')

# Search endpoint
@app.route('/search', methods=['POST'])
@login_required()
def search():
    query = request.form.get('query')

    # Check if the query is cached
    if query in cache:
        results = cache[query]
    else:
        results = []
        for item in data:
            # Fuzzy search using fuzzywuzzy library
            if fuzz.ratio(query, item) >= 70:
                results.append(item)

        # Cache the results
        cache[query] = results

    # Pagination logic
    page, per_page, offset = get_page_args(page_parameter='page', per_page_parameter='per_page')
    pagination = Pagination(page=page, per_page=10, total=len(results), record_name='results')
    results = results[offset: offset + per_page]

    return render_template('results.html', results=results, pagination=pagination)

# Login page
@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form.get('username')
        password = request.form.get('password')

        # Check credentials
        if username in users and users[username]['password'] == password:
            session['username'] = username
            return redirect(url_for('index'))

        error = 'Invalid credentials. Please try again.'
        return render_template('login.html', error=error)

    return render_template('login.html')

# Logout endpoint
@app.route('/logout')
def logout():
    session.clear()
    return redirect(url_for('login'))

if __name__ == '__main__':
    app.run(debug=True)
