Here's a JavaScript function that uses the merge sort algorithm to sort an array of numbers in ascending order. It has a time complexity of O(n log n) and a space complexity of O(n). It does not use any built-in sorting functions or libraries, and does not use recursion:

```javascript
function mergeSort(array) {
  if (array.length <= 1) {
    return array;
  }

  const length = array.length;
  const tempArray = new Array(length);
  let blockSize = 1;

  while (blockSize < length) {
    let i = 0;
    while (i < length) {
      const leftStart = i;
      const leftEnd = Math.min(i + blockSize, length);
      const rightStart = leftEnd;
      const rightEnd = Math.min(rightStart + blockSize, length);

      merge(array, leftStart, leftEnd, rightStart, rightEnd, tempArray);

      i += blockSize * 2;
    }

    // Copy tempArray back to array for next iteration
    for (let j = 0; j < length; j++) {
      array[j] = tempArray[j];
    }

    blockSize *= 2;
  }

  return array;
}

function merge(array, leftStart, leftEnd, rightStart, rightEnd, tempArray) {
  let i = leftStart;
  let j = rightStart;
  let k = leftStart;

  while (i < leftEnd && j < rightEnd) {
    if (array[i] <= array[j]) {
      tempArray[k++] = array[i++];
    } else {
      tempArray[k++] = array[j++];
    }
  }

  while (i < leftEnd) {
    tempArray[k++] = array[i++];
  }

  while (j < rightEnd) {
    tempArray[k++] = array[j++];
  }
}
```

