import java.util.Arrays;

public class StudentGrades {
    private double[] grades;

    public StudentGrades() {
        grades = new double[0];
    }

    public void addGrade(double grade) {
        double[] newGrades = Arrays.copyOf(grades, grades.length + 1);
        newGrades[newGrades.length - 1] = grade;
        grades = newGrades;
    }

    public double calculateAverageGrade() {
        if (grades.length < 3) {
            throw new IllegalArgumentException("At least 3 grades are required to calculate the average.");
        }

        Arrays.sort(grades);

        double sum = 0;
        for (int i = 1; i < grades.length - 1; i++) {
            sum += grades[i];
        }

        return sum / (grades.length - 2);
    }

    public double findHighestGrade() {
        if (grades.length == 0) {
            throw new IllegalStateException("No grades found.");
        }

        double highest = grades[0];
        for (double grade : grades) {
            if (grade > highest) {
                highest = grade;
            }
        }

        return highest;
    }

    public double findLowestGrade() {
        if (grades.length == 0) {
            throw new IllegalStateException("No grades found.");
        }

        double lowest = grades[0];
        for (double grade : grades) {
            if (grade < lowest) {
                lowest = grade;
            }
        }

        return lowest;
    }

    public void displayTop3Grades() {
        if (grades.length < 3) {
            throw new IllegalStateException("At least 3 grades are required to display the top 3 grades.");
        }

        Arrays.sort(grades);

        System.out.println("Top 3 highest grades in descending order:");

        for (int i = grades.length - 1; i >= grades.length - 3; i--) {
            System.out.println(grades[i]);
        }
    }
}
