Here's an example JavaScript program that sorts a given list in ascending order using the merge sort algorithm:

```javascript
function mergeSort(arr) {
  // Base case: if the array is empty or contains only one element, it is already sorted
  if (arr.length <= 1) {
    return arr;
  }

  // Find the middle index of the array
  const mid = Math.floor(arr.length / 2);

  // Divide the array into two halves
  const leftHalf = arr.slice(0, mid);
  const rightHalf = arr.slice(mid);

  // Recursively sort the two halves
  const sortedLeftHalf = mergeSort(leftHalf);
  const sortedRightHalf = mergeSort(rightHalf);

  // Merge the sorted halves
  return merge(sortedLeftHalf, sortedRightHalf);
}

function merge(leftHalf, rightHalf) {
  let result = [];
  let leftIndex = 0;
  let rightIndex = 0;

  // Compare elements from left and right halves and add the smaller element to the result array
  while (leftIndex < leftHalf.length && rightIndex < rightHalf.length) {
    if (leftHalf[leftIndex] < rightHalf[rightIndex]) {
      result.push(leftHalf[leftIndex]);
      leftIndex++;
    } else {
      result.push(rightHalf[rightIndex]);
      rightIndex++;
    }
  }

  // Add remaining elements from the left half (if any)
  while (leftIndex < leftHalf.length) {
    result.push(leftHalf[leftIndex]);
    leftIndex++;
  }

  // Add remaining elements from the right half (if any)
  while (rightIndex < rightHalf.length) {
    result.push(rightHalf[rightIndex]);
    rightIndex++;
  }

  return result;
}

// Example usage
const unsortedList = [5, 3, 8, 1, 2, 7, 4, 6];
const sortedList = mergeSort(unsortedList);
console.log(sortedList); // Output: [1, 2, 3, 4, 5, 6, 7, 8]
```

