def binary_search(data, target, low, high):
    if low > high:
        return -1

    mid = (low + high) // 2
    if data[mid] == target:
        if mid == 0 or data[mid - 1] != target:
            return mid
        else:
            return binary_search(data, target, low, mid - 1)
    elif data[mid] < target:
