function truncateString(str, length) {
  // Check if the string length is greater than the given length
  if (str.length > length) {
    // Truncate the string to the given length
    let truncatedString = str.substring(0, length);

    // Check if the truncated string ends with a partial word
    if (truncatedString.charAt(length - 1) !== ' ') {
      // Find the last space in the truncated string
      let lastSpaceIndex = truncatedString.lastIndexOf(' ');

      // Remove the partial word at the end of the truncated string
      if (lastSpaceIndex !== -1) {
        truncatedString = truncatedString.substring(0, lastSpaceIndex);
      }
    }

    return truncatedString;
  }

  // Return the original string if it is equal to or less than the given length
  return str;
}

