Here is the implementation of a recursive function to sort the strings in the array in reverse order of their lengths using C++:

```cpp
#include <iostream>
#include <string>
using namespace std;

void recursiveSort(string arr[], int n) {
    // Base case
    if (n <= 1) {
        return;
    }

    // Find the index of the longest string
    int maxLenIndex = 0;
    for (int i = 1; i < n; i++) {
        if (arr[i].length() > arr[maxLenIndex].length()) {
            maxLenIndex = i;
        }
    }

    // Swap the longest string with the last string in the array
    swap(arr[maxLenIndex], arr[n - 1]);

    // Recursive call to sort the remaining strings
    recursiveSort(arr, n - 1);
}

