Here is a C++ program that merges two sorted arrays into a single sorted array with unique elements:

```cpp
#include <iostream>
#include <vector>
using namespace std;

vector<int> mergeArrays(const vector<int>& arr1, const vector<int>& arr2) {
    vector<int> mergedArray;
    int i = 0, j = 0;
    int n1 = arr1.size(), n2 = arr2.size();

    // Merge the arrays until one of them is exhausted
    while (i < n1 && j < n2) {
        if (arr1[i] < arr2[j]) {
            if (mergedArray.empty() || mergedArray.back() != arr1[i]) {
                mergedArray.push_back(arr1[i]);
            }
            i++;
        }
        else if (arr1[i] > arr2[j]) {
            if (mergedArray.empty() || mergedArray.back() != arr2[j]) {
                mergedArray.push_back(arr2[j]);
            }
            j++;
        }
        else {
            if (mergedArray.empty() || mergedArray.back() != arr1[i]) {
                mergedArray.push_back(arr1[i]);
            }
            i++;
            j++;
        }
    }

    // Copy the remaining elements of arr1, if any
    while (i < n1) {
        if (mergedArray.empty() || mergedArray.back() != arr1[i]) {
            mergedArray.push_back(arr1[i]);
        }
        i++;
    }

    // Copy the remaining elements of arr2, if any
    while (j < n2) {
        if (mergedArray.empty() || mergedArray.back() != arr2[j]) {
            mergedArray.push_back(arr2[j]);
        }
        j++;
    }

    return mergedArray;
}

int main() {
    vector<int> arr1 = {1, 3, 5, 7, 9};
    vector<int> arr2 = {2, 4, 6, 8, 10, 12};

    vector<int> mergedArray = mergeArrays(arr1, arr2);

    cout << "Merged Array: ";
    for (int num : mergedArray) {
        cout << num << " ";
    }
    cout << endl;

    return 0;
}
```

