Here's a C++ program that sorts a given array in descending order using the bubble sort algorithm, removes any duplicate values from the sorted array, and uses a divide and conquer algorithm to achieve O(nlogn) time complexity:

```cpp
#include <iostream>
#include <algorithm>
#include <vector>
using namespace std;

// Bubble Sort Algorithm to sort the array in descending order
void bubbleSort(vector<int>& arr, int n) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            if (arr[j] < arr[j + 1]) {
                swap(arr[j], arr[j + 1]);
            }
        }
    }
}

// Function to remove duplicate values from the sorted array
vector<int> removeDuplicates(vector<int>& arr) {
    vector<int> result;
    result.push_back(arr[0]);
    int n = arr.size();
    for (int i = 1; i < n; i++) {
        if (arr[i] != arr[i - 1]) {
            result.push_back(arr[i]);
        }
    }
    return result;
}

// Divide and Conquer Algorithm to sort and remove duplicates in O(nlogn) time complexity
vector<int> sortAndRemoveDuplicates(vector<int>& arr, int start, int end) {
    if (start == end) {
        vector<int> result;
        result.push_back(arr[start]);
        return result;
    }
    int mid = (start + end) / 2;
    vector<int> left = sortAndRemoveDuplicates(arr, start, mid);
    vector<int> right = sortAndRemoveDuplicates(arr, mid + 1, end);

    vector<int> merged;
    merge(left.begin(), left.end(), right.begin(), right.end(), back_inserter(merged));

    return removeDuplicates(merged);
}

int main() {
    int n;
    cout << "Enter the number of elements in the array: ";
    cin >> n;

    vector<int> arr(n);
    cout << "Enter the elements of the array: ";
    for (int i = 0; i < n; i++) {
        cin >> arr[i];
    }

    bubbleSort(arr, n);
    vector<int> sortedArr = sortAndRemoveDuplicates(arr, 0, n - 1);

    cout << "Sorted array without duplicates in descending order: ";
    for (int i = 0; i < sortedArr.size(); i++) {
        cout << sortedArr[i] << " ";
    }
    cout << endl;

    return 0;
