    if (num % i === 0) {
      return false;
    }
  }
  return true;
}

function isTwinPrime(num) {
  if (!isPrime(num)) {
    return false;
  }
  if (isPrime(num - 3) || isPrime(num + 3)) {
    return true;
  }
  return false;
}

function isPerfectSquare(num) {
  return Math.sqrt(num) % 1 === 0;
}

function isPalindrome(num) {
  const numStr = num.toString();
  const reversedNumStr = numStr.split('').reverse().join('');
  return numStr === reversedNumStr;
}

function checkNumber(num) {
  const twinPrime = isTwinPrime(num);
  const perfectSquare = isPerfectSquare(num);
  const palindrome = isPalindrome(num);

  if (twinPrime) {
    console.log(num + " is a twin prime number.");
  } else {
