function countDistinctWords(paragraph) {
  // Remove punctuation marks and convert to lowercase
  const formattedParagraph = paragraph.replace(/[^\w\s']/g, '').toLowerCase();

  // Split paragraph into words
  const words = formattedParagraph.split(/\s+/);

  // Create a set to store distinct words
  const distinctWords = new Set();

  // Iterate over each word
  for (let i = 0; i < words.length; i++) {
    const word = words[i];

    // Handle contractions
    if (word.includes("'")) {
      const contractionWords = word.split("'");
      contractionWords.forEach((contractionWord) => {
        // Add each contraction word to the set
        distinctWords.add(contractionWord);
      });
    } else {
      // Add word to the set
      distinctWords.add(word);
    }
  }

  // Return the number of distinct words
  return distinctWords.size;
}
```

