// Function to multiply two matrices
vector<vector<long long>> multiply(vector<vector<long long>>& A, vector<vector<long long>>& B) {
    int rowsA = A.size();
    int colsA = A[0].size();
    int colsB = B[0].size();

    vector<vector<long long>> result(rowsA, vector<long long>(colsB, 0));

    for (int i = 0; i < rowsA; i++) {
        for (int j = 0; j < colsB; j++) {
            for (int k = 0; k < colsA; k++) {
                result[i][j] += A[i][k] * B[k][j];
            }
        }
    }

    return result;
}

// Function to raise a matrix to the power of n
vector<vector<long long>> matrixExponentiation(vector<vector<long long>>& A, int n) {
    if (n == 1) {
        return A;
    }

    vector<vector<long long>> result = matrixExponentiation(A, n / 2);

    result = multiply(result, result);

    if (n % 2 == 1) {
        result = multiply(result, A);
    }

    return result;
}

// Function to generate the Fibonacci sequence using matrix exponentiation
vector<long long> generateFibonacci(int n) {
    vector<long long> fibonacci;

    if (n <= 0) {
        return fibonacci;
    }

    vector<vector<long long>> fibonacciMatrix = {{1, 1}, {1, 0}};

    fibonacciMatrix = matrixExponentiation(fibonacciMatrix, n - 1);

    fibonacci.push_back(fibonacciMatrix[0][0]);

    return fibonacci;
}

int main() {
    int n = 20;

    vector<long long> fibonacci = generateFibonacci(n);

    cout << "Fibonacci sequence up to " << n << " values: ";

    for (int i = 0; i < fibonacci.size(); i++) {
        cout << fibonacci[i] << " ";
    }

    cout << endl;

    return 0;
}

