```cpp
#include <iostream>
#include <string>

int main() {
    int lineCount = 0;
    std::string currentLine = "1";
    int totalDigits = 1;

    while (totalDigits < 100) {
        std::cout << currentLine << std::endl;
        lineCount++;

        int lineDigits = currentLine.length();
        totalDigits += lineDigits;

        if (lineDigits == lineCount) {
            break;
        }

        std::string nextLine = "";
        int currentIndex = 0;

        for (int i = 0; i < lineDigits; i++) {
            int digit = currentLine[i] - '0';

            int left = (i == 0) ? (currentLine[lineDigits - 1] - '0') : (currentLine[i - 1] - '0');
            int right = (i == lineDigits - 1) ? (currentLine[0] - '0') : (currentLine[i + 1] - '0');

            int nextDigit = (digit + left + right) % 10;
            nextLine += std::to_string(nextDigit);

            currentIndex = (currentIndex + 1) % 10;
        }

        currentLine = nextLine;
    }

    return 0;
}
```

