            "Not enough songs by different artists to ensure no consecutive songs by the same artist."
          );
          return;
        }
        continue;
      }

      const randomSongIndex = Math.floor(
        Math.random() * songsByCurrentArtist.length
      );
      const randomSong = songsByCurrentArtist[randomSongIndex];

      shuffledSongs.push(randomSong);
      this.songs.splice(
        this.songs.findIndex(song => song === randomSong),
        1
      );

      prevArtistIndex = currentArtistIndex;
      currentArtistIndex = Math.floor(Math.random() * artistCount);
      if (currentArtistIndex === prevArtistIndex) {
        currentArtistIndex =
          currentArtistIndex === artistCount - 1 ? 0 : currentArtistIndex + 1;
      }
    }

    this.songs = shuffledSongs;
  }
}
