Here is the C++ program to sort an array using the bubble sort algorithm:

```cpp
#include <iostream>
using namespace std;

void bubbleSort(int arr[], int n, int& comparisons, int& swaps) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            comparisons++; // increment comparison count
            if (arr[j] > arr[j + 1]) {
                swaps++; // increment swap count
                // swap arr[j] and arr[j+1]
                int temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
    }
}

int main() {
    const int size = 10;
    int arr[size] = {-52, 71, -6, 94, 0, -83, 31, 55, -32, 79};
    int sortedArr[size];
    int comparisons = 0, swaps = 0;

    // Copying original array to sortedArr
    for (int i = 0; i < size; i++) {
        sortedArr[i] = arr[i];
    }

    bubbleSort(sortedArr, size, comparisons, swaps);

    cout << "Original Array: ";
    for (int i = 0; i < size; i++) {
        cout << arr[i] << " ";
    }

    cout << "\nSorted Array: ";
    for (int i = 0; i < size; i++) {
        cout << sortedArr[i] << " ";
    }

    cout << "\nNumber of comparisons: " << comparisons << endl;
    cout << "Number of swaps: " << swaps << endl;

    return 0;
}
