function generateRandomNumber(min, max, excludedValues, maxAttempts) {
  let randomNum;
  let attempts = 0;

  // Helper function to check if a number is excluded
  function isExcluded(num) {
    return excludedValues.includes(num);
  }

  // Generate a random number and check if it's excluded
  function generateRandom() {
    randomNum = Math.floor(Math.random() * (max - min + 1)) + min;

    if (isExcluded(randomNum)) {
      attempts++;
      if (attempts >= maxAttempts) {
        throw new Error('Max attempts reached');
      }
      generateRandom();
    }
  }

  generateRandom();
  return randomNum;
}
