function customBase64Encode($string) {
    $base64Chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

    // Initialize the result string
    $result = "";

    // Recursive function to encode a chunk of 3 characters
    function encodeChunk($chunk) {
        global $base64Chars, $result;

        // Convert the chunk to binary string
        $binaryChunk = "";
        for ($i = 0; $i < 3; $i++) {
            if ($i < strlen($chunk)) {
                $binaryChunk .= sprintf('%08b', ord($chunk[$i]));
            } else {
                $binaryChunk .= "00000000";
            }
        }

        // Split the binary chunk into 4 groups of 6 bits
        $groups = str_split($binaryChunk, 6);

        // Pad the last group with zeros if necessary
        if (strlen($groups[2]) < 6) {
            $groups[2] .= "00";
        }

        // Convert each group to decimal and use it as an index to get the corresponding base64 character
        for ($i = 0; $i < 4; $i++) {
            $index = bindec($groups[$i]);
            $result .= $base64Chars[$index];
        }
    }

    // Encode each chunk of 3 characters in the string
    function encodeString($string, $startIndex) {
        if ($startIndex >= strlen($string)) {
            return;
        }

        $chunk = substr($string, $startIndex, 3);
        encodeChunk($chunk);

        encodeString($string, $startIndex + 3);
    }

    encodeString($string, 0);

    return $result;
}

