#include <iostream>
using namespace std;

int sumOfDigits(int num) {
    // Base case: if num is a single digit, return the number itself
    if (num >= 0 && num < 10) {
        return num;
    }
    if (num < 0) {
        num = -num;  // convert negative number to positive
    }

    // Recursive case: compute sum of digits for the remaining number
    return (num % 10) + sumOfDigits(num / 10);
}

int main() {
