class Person {
protected:
    std::string name;
    int age;
    std::string address;

public:
    Person(const std::string& name, int age, const std::string& address)
        : name(name), age(age), address(address) {}

    virtual ~Person() {}

    void displayData() const {
        std::cout << "Name: " << name << std::endl;
        std::cout << "Age: " << age << std::endl;
        std::cout << "Address: " << address << std::endl;
    }
};

class Student : public Person {
private:
    std::string studentID;
    std::unique_ptr<int[]> grades;
    int numGrades;
    int maxGrades;

public:
    Student(const std::string& name, int age, const std::string& address, int maxGrades)
        : Person(name, age, address), maxGrades(maxGrades) {
        grades = std::make_unique<int[]>(maxGrades);
        numGrades = 0;
        generateStudentID();
    }

    void addGrade(int grade) {
        if (numGrades < maxGrades) {
            grades[numGrades] = grade;
            numGrades++;
        } else {
            std::cout << "Maximum number of grades reached." << std::endl;
        }
    }

    double calculateAverageGrade() const {
        if (numGrades == 0) {
            return 0.0;
        }

        int sum = 0;
        for (int i = 0; i < numGrades; i++) {
            sum += grades[i];
        }

        return static_cast<double>(sum) / numGrades;
    }

    void displayGrades() const {
        std::cout << "Grades: ";
        for (int i = 0; i < numGrades; i++) {
            std::cout << grades[i] << " ";
        }
        std::cout << std::endl;
    }

    void sortGrades() {
        std::sort(grades.get(), grades.get() + numGrades, std::greater<int>());
    }

    double calculateStandardDeviation() const {
        if (numGrades == 0) {
            return 0.0;
        }

        double mean = calculateAverageGrade();
        double sumSquaredDifferences = 0.0;
        for (int i = 0; i < numGrades; i++) {
            double difference = grades[i] - mean;
            sumSquaredDifferences += difference * difference;
        }

        double variance = sumSquaredDifferences / numGrades;
        return std::sqrt(variance);
    }

    void displayData() const {
        Person::displayData();
        std::cout << "Student ID: " << studentID << std::endl;
    }

private:
    void generateStudentID() {
        const std::string alphanumericChars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
        const int idLength = 12;

        std::random_device rd;
        std::mt19937 generator(rd());
        std::uniform_int_distribution<int> distribution(0, alphanumericChars.size() - 1);

        studentID = "";
        for (int i = 0; i < idLength; i++) {
            studentID += alphanumericChars[distribution(generator)];
        }
    }
};

