def find_common_elements(arr1, arr2):
    # Create two dictionaries to store the occurrences of each element in the arrays
    occurrences1 = {}
    occurrences2 = {}

    # Count the occurrences of each element in arr1 and store them in occurrences1 dictionary
    for num in arr1:
        if num in occurrences1:
            occurrences1[num] += 1
        else:
            occurrences1[num] = 1

    # Count the occurrences of each element in arr2 and store them in occurrences2 dictionary
    for num in arr2:
        if num in occurrences2:
            occurrences2[num] += 1
        else:
            occurrences2[num] = 1

    # Find the common elements by comparing the occurrences in both dictionaries
    common_elements = []
    for num, count in occurrences1.items():
        if num in occurrences2:
            common_elements.extend([num] * min(count, occurrences2[num]))

    return common_elements

