```python
import math
import threading
import time
from concurrent.futures import ThreadPoolExecutor, as_completed
from tqdm import tqdm

def generate_primes(start, end, num_threads):
    primes = []
    chunk_size = math.ceil((end - start) / num_threads)

    def sieve(start, end):
        nonlocal primes
        is_prime = [True] * (end - start + 1)
        sqrt_end = int(math.sqrt(end))

        for i in range(2, sqrt_end + 1):
            if is_prime[i - start]:
                for j in range(i * i, end + 1, i):
                    if j >= start:
                        is_prime[j - start] = False

        for i in range(max(2, start), end + 1):
            if is_prime[i - start]:
                primes.append(i)

    with ThreadPoolExecutor(max_workers=num_threads) as executor:
        futures = []
        for i in range(start, end, chunk_size):
            futures.append(executor.submit(sieve, i, min(i + chunk_size - 1, end)))

        for future in tqdm(as_completed(futures), total=len(futures), unit='chunk'):
            future.result()

    return primes

if __name__ == '__main__':
