public class SquareRootFinder {

    public static double findSquareRoot(int num) {
        if (num < 0) {
            throw new IllegalArgumentException("Cannot find square root of a negative number");
        }

        int guess = num / 3; // Initial guess

        while (true) {
            int square = guess * guess;
            if (square == num) {
                return guess;
            } else if (square > num) {
                guess -= (guess >> 2) + (guess >> 4); // Reduce the guess by one-sixth
            } else {
                guess += guess; // Double the guess
            }

            // Check if the guess is within an acceptable range of the actual square root
            int diff = guess * guess - num;
            if (diff <= 1 && diff >= -1) {
                return guess;
            }
        }
    }

    public static void main(String[] args) {
        int num = 25;
        double squareRoot = findSquareRoot(num);
        System.out.println("Square root of " + num + " is: " + squareRoot);
    }
}
```

