```java
import java.util.Arrays;

public class DynamicArray {
    private int[] array;
    private int size;

    public DynamicArray(int size) {
        this.size = size;
        this.array = new int[size];
    }

    public void set(int index, int value) {
        if (index >= 0 && index < size) {
            array[index] = value;
        } else {
            System.out.println("Invalid index.");
        }
    }

    public int get(int index) {
        if (index >= 0 && index < size) {
            return array[index];
        } else {
            System.out.println("Invalid index.");
            return -1;
        }
    }

    public int calculateSum() {
        int sum = 0;
        for (int i = 0; i < size; i++) {
            sum += array[i];
        }
        return sum;
    }

    public int findMax() {
        int max = Integer.MIN_VALUE;
        for (int i = 0; i < size; i++) {
            if (array[i] > max) {
                max = array[i];
            }
        }
        return max;
    }

    public int findMin() {
        int min = Integer.MAX_VALUE;
        for (int i = 0; i < size; i++) {
            if (array[i] < min) {
                min = array[i];
            }
        }
        return min;
    }

    public void sortDescending() {
        for (int i = 0; i < size; i++) {
            for (int j = i + 1; j < size; j++) {
                if (array[i] < array[j]) {
                    int temp = array[i];
                    array[i] = array[j];
                    array[j] = temp;
                }
            }
        }
    }

    public int[] removeDuplicates() {
        int[] tempArray = Arrays.copyOf(array, size);
        int newSize = size;

        for (int i = 0; i < newSize; i++) {
            for (int j = i + 1; j < newSize; j++) {
                if (tempArray[i] == tempArray[j]) {
                    tempArray[j] = tempArray[newSize - 1];
                    newSize--;
                    j--;
                }
            }
        }

        return Arrays.copyOf(tempArray, newSize);
    }

    public void rotateRight(int positions) {
        positions = positions % size;

        reverse(0, size - 1);
        reverse(0, positions - 1);
        reverse(positions, size - 1);
    }

    private void reverse(int start, int end) {
        while (start < end) {
            int temp = array[start];
            array[start] = array[end];
            array[end] = temp;
            start++;
            end--;
        }
    }

    public int findKthSmallest(int k) {
        if (k <= 0 || k > size) {
            System.out.println("Invalid k value.");
            return -1;
        }

        Arrays.sort(array);
        return array[k - 1];
    }

    public static void main(String[] args) {
        DynamicArray dynamicArray = new DynamicArray(5);

        dynamicArray.set(0, 5);
        dynamicArray.set(1, 10);
        dynamicArray.set(2, 3);
        dynamicArray.set(3, 8);
        dynamicArray.set(4, 2);

        System.out.println("Sum: " + dynamicArray.calculateSum());
        System.out.println("Max: " + dynamicArray.findMax());
        System.out.println("Min: " + dynamicArray.findMin());

        dynamicArray.sortDescending();
        System.out.println("Sorted Array: " + Arrays.toString(dynamicArray.array));

        int[] newArray = dynamicArray.removeDuplicates();
        System.out.println("Array without duplicates: " + Arrays.toString(newArray));

        dynamicArray.rotateRight(2);
        System.out.println("Rotated Array: " + Arrays.toString(dynamicArray.array));

        System.out.println("3rd smallest element: " + dynamicArray.findKthSmallest(3));
    }
}
```

This implementation creates a class called `DynamicArray` that allows the user to create an array of integers with a dynamic size determined by the user. The `set` and `get` methods are used to set and get the values of the array. The `calculateSum` method calculates the sum of all the elements in the array, and the `findMax` and `findMin` methods find the maximum and minimum values in the array, respectively.

The `sortDescending` method sorts the elements of the array in descending order using a simple bubble sort algorithm. The `removeDuplicates` method removes all duplicate elements from the array using a nested loop to compare each element with the rest of the array.

The `rotateRight` method rotates the elements of the array to the right by a given number of positions by reversing the entire array, then reversing the first `positions` elements, and finally reversing the remaining elements.

The `findKthSmallest` method finds the kth smallest element in the array by first sorting the array using `Arrays.sort` and then returning the kth element.

Note that the time complexity mentioned for each method is an estimation and may vary depending on the specific input.

