```java
public class MultiplyNumbers {
    public static int multiply(int a, int b) {
        if (a == 0 || b == 0) {
            return 0;
        }

        boolean isNegative = false;

        if (a < 0 && b < 0) {
            a = negate(a);
            b = negate(b);
        } else if (a < 0 || b < 0) {
            isNegative = true;
            a = negate(a < 0 ? a : b);
            b = Math.abs(b);
        }

        int result = 0;

        while (b != 0) {
            if ((b & 1) != 0) {
                result = add(result, a);
            }

            a <<= 1;
            b >>= 1;
        }

        return isNegative ? negate(result) : result;
    }

    private static int add(int a, int b) {
        while (b != 0) {
            int carry = a & b;
            a ^= b;
            b = carry << 1;
        }

        return a;
    }

    private static int negate(int num) {
        return add(~num, 1);
    }

    public static void main(String[] args) {
        int a = 5;
        int b = 8;

        System.out.println("Product: " + multiply(a, b));
    }
}
```

