```c
#include <stdio.h>

int main() {
    int num, digit, sum = 0, count = 0, even_count = 0;
    float average;

    printf("Enter a positive integer: ");
    scanf("%d", &num);

    while (num > 0) {
        digit = num % 10;
        sum += digit;
        count++;

        if (digit % 2 == 0) {
            even_count++;
        }

        num /= 10;
    }

    average = (float)sum / count;

    printf("Sum of digits: %d\n", sum);
    printf("Average of digits: %.2f\n", average);
    printf("Count of even digits: %d\n", even_count);

    return 0;
}
```

