Here is a JavaScript function that converts a given string to title case, excluding certain words from being capitalized:

```javascript
function convertToTitleCase(str) {
  // Split the string into an array of words
  let words = str.toLowerCase().split(" ");

  // Array of words to exclude from capitalization
  let excludedWords = ["the", "and", "or", "but"];

  // Function to capitalize the first letter of a word
  function capitalize(word) {
    return word.charAt(0).toUpperCase() + word.slice(1);
  }

  // Convert each word to title case
  let titleCaseWords = words.map(function(word) {
    // Check if the word is hyphenated
    if (word.includes("-")) {
      // Split the hyphenated word into subwords
      let subwords = word.split("-");

      // Convert each subword to title case
      let subwordTitleCase = subwords.map(function(subword) {
        // Capitalize the subword if it is not excluded
        return excludedWords.includes(subword) ? subword : capitalize(subword);
      });

      // Join the subwords back into a hyphenated word
      return subwordTitleCase.join("-");
    }

    // Capitalize the word if it is not excluded
    return excludedWords.includes(word) ? word : capitalize(word);
  });

  // Join the title case words back into a string
  return titleCaseWords.join(" ");
}

// Example usage
console.log(convertToTitleCase("the quick brown fox jumps over the lazy dog"));
// Output: "The Quick Brown Fox Jumps over the Lazy Dog"

console.log(convertToTitleCase("i love JavaScript"));
// Output: "I Love JavaScript"

console.log(convertToTitleCase("web-design and development"));
// Output: "Web-Design and Development"

console.log(convertToTitleCase("but not this"));
// Output: "But not This"
```

This function first splits the given string into an array of words, and converts each word to lowercase. It then iterates over each word and checks if it should be excluded from capitalization. If the word is hyphenated, it splits the word into subwords and converts each subword to title case. Finally, it joins the title case words back into a string and returns the result.

