function sumOfPrimes(n) {
  var sum = 0;
  var count = 0;

  for (var i = 2; count < n; i++) {
    if (isPrime(i)) {
      sum += i;
      count++;
    }
  }

  return sum;
}

function isPrime(num) {
  for (var i = 2, sqrt = Math.sqrt(num); i <= sqrt; i++) {
    if (num % i === 0) {
      return false;
    }
  }

  return num > 1;
}

