```matlab
function [root1, root2] = quadraticRoots(a, b, c)
    % Check if a = 0 or b = 0
    if a == 0
        root1 = -c/b;
        root2 = root1;
    elseif b == 0
        root1 = sqrt(-c/a);
        root2 = -root1;
    else
        % Calculate discriminant
        discriminant = b^2 - 4*a*c;

        % Check discriminant
        if discriminant < 0
            % Complex roots
            realPart = -b / (2*a);
            imaginaryPart = sqrt(-discriminant) / (2*a);
            root1 = complex(realPart, imaginaryPart);
            root2 = complex(realPart, -imaginaryPart);
        else
            % Real roots
            root1 = (-b + sqrt(discriminant)) / (2*a);
            root2 = (-b - sqrt(discriminant)) / (2*a);
        end
    end
end
