import java.util.Objects;

public class ComplexNumber {
    private double real;
    private double imaginary;

    public ComplexNumber(double real, double imaginary) {
        this.real = real;
        this.imaginary = imaginary;
    }

    public double getReal() {
        return real;
    }

    public double getImaginary() {
        return imaginary;
    }

    public double getMagnitude() {
        return Math.sqrt(real * real + imaginary * imaginary);
    }

    public double getPhase() {
        return Math.atan2(imaginary, real);
    }

    public ComplexNumber getConjugate() {
        return new ComplexNumber(real, -imaginary);
    }

    public ComplexNumber add(ComplexNumber other) {
        double realPart = this.real + other.real;
        double imaginaryPart = this.imaginary + other.imaginary;
        return new ComplexNumber(realPart, imaginaryPart);
    }

    public ComplexNumber subtract(ComplexNumber other) {
        double realPart = this.real - other.real;
        double imaginaryPart = this.imaginary - other.imaginary;
        return new ComplexNumber(realPart, imaginaryPart);
    }

    public ComplexNumber multiply(ComplexNumber other) {
        double realPart = this.real * other.real - this.imaginary * other.imaginary;
        double imaginaryPart = this.real * other.imaginary + this.imaginary * other.real;
        return new ComplexNumber(realPart, imaginaryPart);
    }

    public ComplexNumber divide(ComplexNumber other) {
        double denominator = other.real * other.real + other.imaginary * other.imaginary;
        double realPart = (this.real * other.real + this.imaginary * other.imaginary) / denominator;
        double imaginaryPart = (this.imaginary * other.real - this.real * other.imaginary) / denominator;
        return new ComplexNumber(realPart, imaginaryPart);
    }

    public boolean equals(ComplexNumber other) {
        return this.real == other.real && this.imaginary == other.imaginary;
    }

    public int compareMagnitude(ComplexNumber other) {
        double magnitude1 = this.getMagnitude();
        double magnitude2 = other.getMagnitude();
        return Double.compare(magnitude1, magnitude2);
    }

    public boolean isPureImaginary() {
        return real == 0 && imaginary != 0;
    }

    public boolean isPureReal() {
        return real != 0 && imaginary == 0;
    }

    public ComplexNumber getExponentialForm() {
        double exponent = Math.exp(real);
        double realPart = exponent * Math.cos(imaginary);
        double imaginaryPart = exponent * Math.sin(imaginary);
        return new ComplexNumber(realPart, imaginaryPart);
    }

    public ComplexNumber getSquareRoot() {
        double magnitude = this.getMagnitude();
        double realPart = Math.sqrt((magnitude + real) / 2);
        double imaginaryPart = Math.sqrt((magnitude - real) / 2);
        if (imaginary < 0) {
            imaginaryPart = -imaginaryPart;
        }
        return new ComplexNumber(realPart, imaginaryPart);
    }

    public ComplexNumber getNthPower(int n) {
        double magnitude = Math.pow(this.getMagnitude(), n);
        double phase = this.getPhase() * n;
        double realPart = magnitude * Math.cos(phase);
        double imaginaryPart = magnitude * Math.sin(phase);
        return new ComplexNumber(realPart, imaginaryPart);
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        ComplexNumber that = (ComplexNumber) o;
        return Double.compare(that.real, real) == 0 && Double.compare(that.imaginary, imaginary) == 0;
    }

    @Override
    public int hashCode() {
        return Objects.hash(real, imaginary);
    }

    @Override
    public String toString() {
        return real + " + " + imaginary + "i";
    }
}
