  if (size < 1) {
    return [];
  }

  // Check if characters is an empty string, return array filled with empty strings
  if (characters === '') {
    return Array(size).fill('');
  }

  // Remove duplicate characters and ignore non-letter characters
  const uniqueChars = Array.from(new Set(characters.toLowerCase().match(/[a-z]/g)));

  // Sort the characters based on ASCII value
  uniqueChars.sort((a, b) => a.charCodeAt(0) - b.charCodeAt(0));

  // Fill the array with the unique characters
  const result = Array(size).fill('');
  for (let i = 0; i < Math.min(size, uniqueChars.length); i++) {
