        if not isinstance(grade, float) or grade < 0 or grade > 100:
            raise ValueError("Grade must be a float between 0 and 100 (inclusive).")
        self.subjects[subject_name] = grade

    def calculate_average(self):
        num_subjects = len(self.subjects)
        subject_grades_sum = sum(self.subjects.values())
        subject_average = subject_grades_sum / num_subjects if num_subjects > 0 else 0
        return (subject_average + self.grade) / 2

    def increase_grade(self, percentage):
        if not isinstance(percentage, float) or percentage < 0:
            raise ValueError("Percentage must be a positive float value.")
        for subject in self.subjects:
            self.subjects[subject] += self.subjects[subject] * (percentage / 100)


