class Stack:
    def __init__(self):
        self.stack = []
        self.min_stack = []
        self.capacity = 100

    def push(self, item):
        if len(self.stack) == self.capacity:
            return "Stack is full"
        else:
            self.stack.append(item)
            if len(self.min_stack) == 0 or item <= self.min_stack[-1]:
                self.min_stack.append(item)

    def pop(self):
        if len(self.stack) == 0:
            return "Stack is empty"
        else:
            item = self.stack.pop()
            if item == self.min_stack[-1]:
                self.min_stack.pop()

    def peek(self):
        if len(self.stack) == 0:
            return "Stack is empty"
        else:
            return self.stack[-1]

    def get_minimum(self):
        if len(self.stack) == 0:
            return "Stack is empty"
        else:
            return self.min_stack[-1]

    def reverse(self):
        if len(self.stack) == 0:
            return "Stack is empty"
        else:
            self.stack.reverse()

    def is_empty(self):
        return len(self.stack) == 0

    def is_full(self):
        return len(self.stack) == self.capacity


