import React, { useState, useEffect } from "react";

const Clock = () => {
  const [currentTime, setCurrentTime] = useState(new Date());
  const [countdown, setCountdown] = useState(5 * 60 * 1000);
  const [isTimeUp, setIsTimeUp] = useState(false);

  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentTime(new Date());
      setCountdown((prevCountdown) => prevCountdown - 1);
    }, 1);

    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    if (countdown === 0) {
      setIsTimeUp(true);
      clearInterval(interval);
    }
  }, [countdown]);

  const getFormattedTime = (time) => {
    const options = {
      hour: "numeric",
      minute: "numeric",
      second: "numeric",
    };

    return time.toLocaleString(undefined, options);
  };

  const getFormattedDate = (date) => {
    const options = {
      weekday: "long",
      month: "long",
      day: "numeric",
      year: "numeric",
    };

    return date.toLocaleString(undefined, options);
  };

  const getFormattedCountdown = (countdown) => {
    const minutes = Math.floor(countdown / 60000);
    const seconds = Math.floor((countdown % 60000) / 1000);

    return `${minutes.toString().padStart(2, "0")}:${seconds
      .toString()
      .padStart(2, "0")}`;
  };

  return (
    <div>
      <div>
        {getFormattedDate(currentTime)} - {getFormattedTime(currentTime)}
      </div>
      <div>{isTimeUp ? "Time's up!" : getFormattedCountdown(countdown)}</div>
    </div>
  );
};

export default Clock;

