    population: 2704958,
    averageTemperature: 52,
    attractions: 67
  },
  // add more cities here
];

const CityTable = () => {
  const [sortConfig, setSortConfig] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');

  const handleSort = (columnName) => {
    if (sortConfig && sortConfig.key === columnName) {
      setSortConfig({
        key: columnName,
        direction: sortConfig.direction === 'ascending' ? 'descending' : 'ascending'
      });
    } else {
      setSortConfig({ key: columnName, direction: 'ascending' });
    }
  };

  const handleSearch = (event) => {
    setSearchTerm(event.target.value);
  };

  const filteredCities = cities.filter((city) =>
    city.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    city.population.toString().includes(searchTerm)
  );

  const sortedCities = filteredCities.sort((a, b) => {
    if (!sortConfig) return 0;

    const { key, direction } = sortConfig;

    if (a[key] < b[key]) {
      return direction === 'ascending' ? -1 : 1;
    }
    if (a[key] > b[key]) {
      return direction === 'ascending' ? 1 : -1;
    }
    return 0;
  });

  return (
    <div>
      <input type="text" placeholder="Search..." value={searchTerm} onChange={handleSearch} />
      <table>
        <thead>
          <tr>
            <th onClick={() => handleSort('name')}>City Name</th>
            <th onClick={() => handleSort('population')}>Population</th>
            <th onClick={() => handleSort('averageTemperature')}>Average Temperature</th>
            <th onClick={() => handleSort('attractions')}>Number of Tourist Attractions</th>
          </tr>
        </thead>
        <tbody>
          {sortedCities.map((city) => (
            <tr key={city.name}>
              <td>{city.name}</td>
              <td>{city.population}</td>
              <td>{city.averageTemperature}</td>
              <td>{city.attractions}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default CityTable;
```

