function alertRandomMessage(messages) {
  let previousMessage = '';

  function getRandomIndex() {
    return Math.floor(Math.random() * messages.length);
  }

  function selectMessage() {
    let randomIndex = getRandomIndex();
    let selectedMessage = messages[randomIndex];

    // If the selected message is the same as the previous one, recursively call selectMessage() to get a different one
    if (selectedMessage === previousMessage) {
      return selectMessage();
    }

    previousMessage = selectedMessage;
    alert(selectedMessage);
  }

  selectMessage();
}
