    if (index >= size) {
        return 0;
    }

    return arr[index] + calculateSum(arr, size, index + 2);
}

// Function to calculate the product of elements at even indices
int calculateProduct(int* arr, int size, int index = 0) {
    if (index >= size) {
        return 1;
    }

    return arr[index] * calculateProduct(arr, size, index + 2);
}

// Function to check if the array is sorted in ascending order
bool isSorted(int* arr, int size, int index = 1) {
    if (index >= size) {
        return true;
    }

    if (arr[index] < arr[index - 1]) {
        return false;
    }

    return isSorted(arr, size, index + 1);
}

// Function to display the sum, product, and sorting result
