```python
def count_items(lst):
    count_dict = {}

    for item in lst:
        if isinstance(item, list):
            # Flatten the nested list and count items
            nested_count_dict = count_items(item)
            for key, value in nested_count_dict.items():
                count_dict[key] = count_dict.get(key, 0) + value
        elif isinstance(item, dict):
            # Count the occurrences of each key in the dictionary
            for key, value in item.items():
                count_dict[key] = count_dict.get(key, 0) + value
        else:
            # Count the item itself
            count_dict[item] = count_dict.get(item, 0) + 1

    return count_dict
