from typing import List

class Person:
    def __init__(self, name: str, age: int, occupation: str, address: str):
        self.name = name
        self.age = age
        self.occupation = occupation
        self.address = address

    def calculate_salary(self, years_of_experience: int, qualifications: List[str], currency: str = 'USD') -> int:
        try:
            conversion_rate = self.get_conversion_rate(currency)
        except:
            conversion_rate = 1.0

        salary = 0
        for qualification in qualifications:
            relevance = self.get_qualification_relevance(qualification)
            salary += relevance

        salary += years_of_experience * 1000
        salary *= conversion_rate

        return round(salary)

    def get_conversion_rate(self, currency: str) -> float:
        # Fetch the conversion rate from an external API and return it
        # Here, we are assuming the API returns the conversion rate as 1.0 for USD
        if currency == 'USD':
            return 1.0
        else:
            response = requests.get(f"https://api.example.com/currency?base=USD&target={currency}")
            data = response.json()
