def play_tic_tac_toe():
    board = [[' ' for _ in range(4)] for _ in range(4)]
    current_player = 'X'

    def print_board():
        print('---------')
        for row in board:
            print('|', end='')
            for cell in row:
                print(cell, end='|')
            print('\n---------')

    def check_winner():
        # Check rows
        for row in board:
            if row[0] == row[1] == row[2] == row[3] != ' ':
                return True

        # Check columns
        for col in range(4):
            if board[0][col] == board[1][col] == board[2][col] == board[3][col] != ' ':
                return True

        # Check diagonals
        if board[0][0] == board[1][1] == board[2][2] == board[3][3] != ' ':
            return True
        if board[0][3] == board[1][2] == board[2][1] == board[3][0] != ' ':
            return True

        return False

    def is_board_full():
        for row in board:
            if ' ' in row:
                return False
        return True

    def make_move():
        while True:
            try:
                row = int(input("Enter the row (0-3): "))
                col = int(input("Enter the column (0-3): "))
                if board[row][col] == ' ':
                    board[row][col] = current_player
                    break
                else:
                    print("Invalid move! Try again.")
            except ValueError:
                print("Invalid input! Try again.")

    while True:
        print_board()
        make_move()

        if check_winner():
            print_board()
            print(f"Player {current_player} wins!")
            break

        if is_board_full():
            print_board()
            print("It's a tie!")
            break

        current_player = 'O' if current_player == 'X' else 'X'


play_tic_tac_toe()
```

