To find the Nth prime Fibonacci number efficiently without generating all Fibonacci numbers up to that point, we can use a modified version of the Sieve of Eratosthenes algorithm. Here's a Python program that meets the requirements:

```python
def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def nth_prime_fibonacci(n):
    if n <= 0:
        return None

    count = 0
    a, b = 0, 1

    while count < n:
        if is_prime(b):
            count += 1
        a, b = b, a + b

    return a

# Read input from user
