Here is an example of a custom sorting algorithm in C that sorts elements in descending order with a time complexity of O(n log n):

```c
#include <stdio.h>

void merge(int arr[], int left[], int leftSize, int right[], int rightSize) {
    int i = 0, j = 0, k = 0;

    while (i < leftSize && j < rightSize) {
        if (left[i] >= right[j])
            arr[k++] = left[i++];
        else
            arr[k++] = right[j++];
    }

    while (i < leftSize)
        arr[k++] = left[i++];

    while (j < rightSize)
        arr[k++] = right[j++];
}

void mergeSort(int arr[], int size) {
    if (size < 2)
        return;

    int mid = size / 2;
    int left[mid];
    int right[size - mid];

    for (int i = 0; i < mid; i++)
        left[i] = arr[i];

    for (int i = mid; i < size; i++)
        right[i - mid] = arr[i];

    mergeSort(left, mid);
    mergeSort(right, size - mid);
    merge(arr, left, mid, right, size - mid);
}

int main() {
    int arr[] = {5, 2, 9, 1, 7, 3};
    int size = sizeof(arr) / sizeof(arr[0]);

    printf("Original Array: ");
    for (int i = 0; i < size; i++)
        printf("%d ", arr[i]);

    mergeSort(arr, size);

    printf("\nSorted Array (Descending Order): ");
    for (int i = 0; i < size; i++)
        printf("%d ", arr[i]);

    return 0;
}
```

This code demonstrates a sorting algorithm called merge sort, which has a time complexity of O(n log n). It recursively divides the array into two halves until each half contains only one element. Then, it merges the two halves in descending order until the entire array is sorted.

