```php
function calculateDateDifference($date1, $date2) {
    $minDate = '1800-01-01';
    $maxDate = '2200-12-31';

    // Validate input format and range
    if (!preg_match('/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/', $date1) || !preg_match('/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/', $date2)) {
        return 'Invalid date format. Please use the format "YYYY-MM-DD HH:mm:ss".';
    }

    if ($date1 < $minDate || $date1 > $maxDate || $date2 < $minDate || $date2 > $maxDate) {
        return 'Invalid date range. Please use dates between 1800-01-01 and 2200-12-31.';
    }

    // Convert dates to DateTime objects and handle timezones
    $timezone = new DateTimeZone('UTC');
    $dateTime1 = new DateTime($date1, $timezone);
    $dateTime2 = new DateTime($date2, $timezone);

    // Calculate difference in seconds
    $difference = $dateTime2->getTimestamp() - $dateTime1->getTimestamp();

    // Calculate difference in months, weeks, days, hours, minutes, and seconds
    $months = floor($difference / (30 * 24 * 60 * 60));
    $weeks = floor(($difference % (30 * 24 * 60 * 60)) / (7 * 24 * 60 * 60));
    $days = floor(($difference % (7 * 24 * 60 * 60)) / (24 * 60 * 60));
    $hours = floor(($difference % (24 * 60 * 60)) / (60 * 60));
    $minutes = floor(($difference % (60 * 60)) / 60);
    $seconds = $difference % 60;

    // Return the calculated difference
    return "Months: $months, Weeks: $weeks, Days: $days, Hours: $hours, Minutes: $minutes, Seconds: $seconds";
}

