        System.out.println("Are the strings anagrams? " + areAnagrams);

        // Count the occurrences of each character in both strings
        Map<Character, Integer> charCountMap = countCharacters(str1 + str2);

        // Display the characters along with their counts
        System.out.println("Character counts:");
        for (Map.Entry<Character, Integer> entry : charCountMap.entrySet()) {
            System.out.println(entry.getKey() + ": " + entry.getValue());
        }

        // Output the anagrams in alphabetical order
        System.out.println("Anagrams in alphabetical order:");
        List<Character> sortedCharacters = new ArrayList<>(charCountMap.keySet());
        Collections.sort(sortedCharacters);
        for (char c : sortedCharacters) {
            int count = charCountMap.get(c);
            System.out.println(c + ": " + count);
        }
    }

    // Method to check if two strings are anagrams of each other
    public static boolean checkAnagrams(String str1, String str2) {
        if (str1.length() != str2.length()) {
            return false;
        }

        char[] charArray1 = str1.toCharArray();
        char[] charArray2 = str2.toCharArray();

        Arrays.sort(charArray1);
        Arrays.sort(charArray2);

        return Arrays.equals(charArray1, charArray2);
    }

    // Method to count the occurrences of each character in a string
    public static Map<Character, Integer> countCharacters(String str) {
        Map<Character, Integer> charCountMap = new HashMap<>();

        for (char c : str.toCharArray()) {
            charCountMap.put(c, charCountMap.getOrDefault(c, 0) + 1);
        }

        return charCountMap;
