```javascript
function generateCombinations(elements, length) {
  const combinations = [];

  function backtrack(combination, start) {
    if (combination.length === length) {
      combinations.push(combination.slice());
      return;
    }

    for (let i = start; i < elements.length; i++) {
      combination.push(elements[i]);
      backtrack(combination, i + 1);
      combination.pop();
    }
  }

  backtrack([], 0);

  return combinations;
}
