function changeColor(element, color, condition) {
  // Check if element is visible
  if (window.getComputedStyle(element).display === "none" || window.getComputedStyle(element).opacity === "0") {
    return;
  }

  // Check if condition is met
  if (condition && !condition(element)) {
    return;
  }

  // Change color of current element
  element.style.color = color;

  // Recursively change color of child elements
  const childElements = element.querySelectorAll("*");
  for (let i = 0; i < childElements.length; i++) {
    changeColor(childElements[i], color, condition);
  }
}
