function capitalizeString(str) {
  // Remove any numbers or special characters
  let cleanedStr = str.replace(/[^\w\s]|_/g, "").replace(/\s+/g, " ");

  // Split the string into an array of words
  let words = cleanedStr.split(" ");

  // Capitalize the first letter of each word
  let capitalizedWords = words.map(word => {
    // Ignore articles at the beginning of each word
    if (["a", "an", "the"].includes(word.toLowerCase())) {
      return word;
    }
    return word.charAt(0).toUpperCase() + word.slice(1);
  });

  // Join the capitalized words into a single string
  let capitalizedStr = capitalizedWords.join(" ");

  return capitalizedStr;
}
