def calculate_product(nums):
    if len(nums) == 0:
        raise EmptyListError("List is empty.")
    if len(nums) > 10:
        raise ListLengthError("List length exceeds the maximum length of 10.")

    # Check for negative numbers
    if any(num < 0 for num in nums):
        raise NegativeNumberError("List contains negative numbers.")

    count_zeros = nums.count(0)

    # Remove zeros from the list if count is even
    if count_zeros % 2 == 0:
        nums = [num for num in nums if num != 0]
    else:
        return 0

    # Calculate the product using logarithmic approach
    return calculate_product_recursive(nums)

def calculate_product_recursive(nums):
    n = len(nums)

    if n == 1:
        return nums[0]

    if n % 2 == 0:
        mid = n // 2
        return calculate_product_recursive(nums[:mid]) * calculate_product_recursive(nums[mid:]) * nums[mid]
    else:
        mid = n // 2
        return calculate_product_recursive(nums[:mid]) * calculate_product_recursive(nums[mid:])

# Example usage:
