class Interface {
public:
    virtual void processInteger(int num) = 0;
    virtual void processString(const std::string& str) = 0;
};

class Implementation : public Interface {
public:
    void processInteger(int num) override {
        if (num <= 1 || num >= 1000000000) {
            std::cout << "Error: Integer must be a positive number less than 10^9." << std::endl;
            return;
        }

        if (!isPrime(num)) {
            std::cout << "Error: Integer is not prime." << std::endl;
            return;
        }

        // Further processing for prime number
        std::cout << "Processing integer: " << num << std::endl;
    }

    void processString(const std::string& str) override {
        if (str.empty() || str.length() > 1000) {
            std::cout << "Error: String must be non-empty with a maximum length of 1000 characters." << std::endl;
            return;
        }

        if (!isPalindrome(str)) {
            std::cout << "Error: String is not a palindrome." << std::endl;
            return;
        }

        // Further processing for palindrome string
        std::cout << "Processing string: " << str << std::endl;
    }

private:
    bool isPrime(int num) {
        if (num <= 1)
            return false;

        if (num <= 3)
            return true;

        if (num % 2 == 0 || num % 3 == 0)
            return false;

        int sqrtNum = sqrt(num);

        for (int i = 5; i <= sqrtNum; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0)
                return false;
        }

        return true;
    }

    bool isPalindrome(const std::string& str) {
        int length = str.length();

        for (int i = 0; i < length / 2; i++) {
            if (str[i] != str[length - i - 1])
                return false;
        }

        return true;
    }
};

int main() {
    Implementation impl;
    impl.processInteger(7);
    impl.processInteger(12);
    impl.processString("racecar");
    impl.processString("hello");

    return 0;
}
```

