// Function to count the number of duplicate elements in an array
int countDuplicates(int arr[], int size) {
    int count = 0;
    for (int i = 0; i < size; i++) {
        // Check if the current element is a duplicate
        bool isDuplicate = false;
        for (int j = i + 1; j < size; j++) {
            if (arr[i] == arr[j]) {
                isDuplicate = true;
                break;
            }
        }
        if (isDuplicate) {
            count++;
        }
    }
    return count;
}

// Function to return an array of duplicate elements in ascending order
int* findDuplicates(int arr[], int size, int& resultSize) {
    int numDuplicates = countDuplicates(arr, size);
    int* duplicates = new int[numDuplicates];
    int index = 0;
    for (int i = 0; i < size; i++) {
        // Check if the current element is a duplicate
        bool isDuplicate = false;
        for (int j = i + 1; j < size; j++) {
            if (arr[i] == arr[j]) {
                isDuplicate = true;
                break;
            }
        }
        if (isDuplicate) {
            // Check if the duplicate element is already in the duplicates array
            bool isExisting = false;
            for (int k = 0; k < index; k++) {
                if (arr[i] == duplicates[k]) {
                    isExisting = true;
                    break;
                }
            }
            if (!isExisting) {
                duplicates[index] = arr[i];
                index++;
            }
        }
    }
    resultSize = numDuplicates;
    return duplicates;
}

